import { NextResponse } from 'next/server'
import { createClient } from '../../../../utils/supabase/server'

// 1. PUT: แก้ไขข้อมูลครุภัณฑ์ (หรือเปลี่ยนสถานะ)
export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const supabase = await createClient()
  const { id } = await params // รับ id จาก URL เช่น /api/assets/5

  try {
    const body = await request.json()
    const { name, brand, asset_code, serial_number, contract_number, status, type } = body

    const { data, error } = await supabase
      .from('assets')
      .update({ 
        name, 
        brand, 
        asset_code,
        serial_number, 
        contract_number, 
        status,
        type
      })
      .eq('id', id)
      .select()

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 })
    }

    return NextResponse.json({ success: true, message: 'อัปเดตข้อมูลสำเร็จ', data: data[0] })
  } catch (err) {
    return NextResponse.json({ error: 'รูปแบบข้อมูลไม่ถูกต้อง' }, { status: 400 })
  }
}

// 2. DELETE: ลบครุภัณฑ์ออกชั่วคราว/ถาวร
export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const supabase = await createClient()
  const { id } = await params

  const { error } = await supabase
    .from('assets')
    .delete()
    .eq('id', id)

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ success: true, message: `ลบครุภัณฑ์ ID: ${id} เรียบร้อยแล้ว` })
}

import { NextResponse } from 'next/server'
import { createClient } from '../../../utils/supabase/server'

// 1. GET: ดึงรายการครุภัณฑ์ทั้งหมด
export async function GET() {
  try {
    console.log('[GET /api/assets] Starting request...')
    const supabase = await createClient()
    console.log('[GET /api/assets] Supabase client created')
    
    const { data: assets, error } = await supabase
      .from('assets')
      .select('*')
      .order('created_at', { ascending: false }) // เอาตัวใหม่ขึ้นก่อน

    if (error) {
      console.error('[GET /api/assets] Supabase error:', error)
      return NextResponse.json({ error: error.message }, { status: 500 })
    }

    console.log('[GET /api/assets] Success, returned', assets?.length, 'assets')
    return NextResponse.json({ success: true, data: assets })
  } catch (err) {
    console.error('[GET /api/assets] Exception:', err)
    return NextResponse.json({ error: String(err) }, { status: 500 })
  }
}

// 2. POST: เพิ่มครุภัณฑ์ชิ้นใหม่
export async function POST(request: Request) {
  const supabase = await createClient()

  try {
    const body = await request.json()
    const { name, brand, asset_code, serial_number, contract_number, status, type } = body

    if (!name) {
      return NextResponse.json({ error: 'กรุณาระบุชื่อสินทรัพย์ (name)' }, { status: 400 })
    }

    const { data, error } = await supabase
      .from('assets')
      .insert([
        { 
          name, 
          brand: brand || null,
          asset_code: asset_code || null, 
          serial_number: serial_number || null,
          contract_number: contract_number || null,
          status: status || 'Available',
          type: type || null
        }
      ])
      .select()

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 })
    }

    return NextResponse.json({ success: true, data: data[0] }, { status: 201 })
  } catch (err) {
    return NextResponse.json({ error: 'รูปแบบข้อมูลไม่ถูกต้อง' }, { status: 400 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '../../../../utils/supabase/server'


// PUT: บันทึกการ "คืนอุปกรณ์" (อัปเดต return_date และเปลี่ยนสถานะ Asset กลับเป็น Available)
export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const supabase = await createClient()
  const { id } = await params // คืนรายการ borrows ID นี้

  try {
    const body = await request.json()
    // รับ asset_id มาด้วยเพื่อสลับสถานะตัวเครื่องคืนให้
    const { asset_id, return_date } = body 

    if (!asset_id) {
      return NextResponse.json({ error: 'กรุณาระบุ asset_id เพื่อทำการคืนสินทรัพย์' }, { status: 400 })
    }

    const actualReturnDate = return_date || new Date().toISOString()

    // 1. อัปเดตตาราง borrows บันทึกวันส่งคืน
    const { data: borrowData, error: borrowError } = await supabase
      .from('borrows')
      .update({ return_date: actualReturnDate })
      .eq('id', id)
      .select()

    if (borrowError) {
      return NextResponse.json({ error: borrowError.message }, { status: 500 })
    }

    // 2. ปลดล็อกสถานะในตาราง assets กลับมาเป็น 'Available' เพื่อให้คนอื่นยืมต่อได้
    await supabase
      .from('assets')
      .update({ status: 'Available' })
      .eq('id', asset_id)

    return NextResponse.json({ 
      success: true, 
      message: 'บันทึกการคืนสินทรัพย์สำเร็จและปลดล็อกตัวเครื่องแล้ว', 
      data: borrowData[0] 
    })

  } catch (err) {
    return NextResponse.json({ error: 'รูปแบบข้อมูลไม่ถูกต้อง' }, { status: 400 })
  }
}

// 🗑️ ฟังก์ชันรองรับการลบครุภัณฑ์รายชิ้น
export async function DELETE(
  request: Request,
  context: { params: Promise<{ id: string }> } // <--- แก้ตรงนี้ครับช่าง
) {
  try {
    // ต้อง await params ก่อนดึงค่า id ออกมา
    const { id: assetId } = await context.params; 

    if (!assetId) {
      return NextResponse.json({ success: false, error: 'ไม่พบ ID ของครุภัณฑ์' }, { status: 400 });
    }

    const supabase = await createClient();

    // 🔒 1. ด่านเช็คซ้ำฝั่งหลังบ้าน: เครื่องโดนยืมอยู่ ห้ามลบ!
    const { data: asset, error: checkError } = await supabase
      .from('assets')
      .select('status')
      .eq('id', assetId)
      .single();

    if (checkError) throw checkError;
    if (asset?.status === 'Borrowed' || asset?.status === 'borrowed') {
      return NextResponse.json({ success: false, error: 'ครุภัณฑ์นี้กำลังถูกยืมอยู่ ไม่สามารถลบได้' }, { status: 400 });
    }

    // ⚡ 2. ปลดล็อก Foreign Key
    const { error: updateBorrowError } = await supabase
      .from('borrows')
      .update({ asset_id: null })
      .eq('asset_id', assetId);

    if (updateBorrowError) {
      console.error('ปลดล็อก Foreign Key ใน borrows ไม่สำเร็จ:', updateBorrowError.message);
      throw updateBorrowError;
    }

    // 🗑️ 3. สั่งลบอุปกรณ์จริง
    const { error: deleteError } = await supabase
      .from('assets')
      .delete()
      .eq('id', assetId);

    if (deleteError) throw deleteError;

    return NextResponse.json({ success: true, message: 'ลบครุภัณฑ์ออกจากระบบสำเร็จ' });

  } catch (error: any) {
    console.error('Delete asset error:', error.message);
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@/utils/supabase/server' 

export async function GET() {
  try {
    const supabase = await createClient()

    // 1. ดึงข้อมูลรายการยืม (Borrows) และอุปกรณ์ (Assets)
    const { data: borrows, error: borrowError } = await supabase
      .from('borrows')
      .select(`
        *,
        assets ( id, name, brand, serial_number, type )
      `)
      .order('id', { ascending: false })

    if (borrowError) throw borrowError

    // 2. ดึงข้อมูลเอกสารทั้งหมด (Documents) โดยดึงทุกคอลัมน์มาดูก่อน
    const { data: documents, error: docError } = await supabase
      .from('documents')
      .select('*')

    if (docError) throw docError

    // 3. รวมร่างข้อมูลด้วยลอจิก "เช็กทุกคอลัมน์ที่น่าจะเป็น ID เชื่อม"
    const historyWithDocs = borrows.map((borrow) => {
      // ตรงนี้คือหัวใจสำคัญ: สแกนว่าในตารางเอกสาร มีแถวไหนที่เลข ID ตรงกับรายการยืมนี้บ้าง
      const linkedDocuments = documents.filter((doc) => {
        const borrowId = Number(borrow.id)
        return (
          Number(doc.borrow_id) === borrowId || 
          Number(doc.borrow_id_int) === borrowId
        )
      })

      return {
        ...borrow,
        documents: linkedDocuments,
        // ส่ง file_url ตรงไปให้หน้าบ้านเช็กง่ายๆ
        file_url: linkedDocuments.length > 0 ? linkedDocuments[0].file_url : null
      }
    })

    return NextResponse.json({ success: true, history: historyWithDocs })
  } catch (err: any) {
    console.error('❌ API Error Detail:', err)
    return NextResponse.json(
      { success: false, error: err.message || 'Server Error' }, 
      { status: 500 }
    )
  }
}

export async function PATCH(request: Request) {
  try {
    const supabase = await createClient()
    const { borrowId, assetId } = await request.json()

    if (!borrowId || !assetId) {
      return NextResponse.json({ success: false, error: 'ข้อมูลไม่ครบถ้วน' }, { status: 400 })
    }

    // อัปเดตวันที่คืน
    const { error: borrowError } = await supabase
      .from('borrows')
      .update({ return_date: new Date().toISOString() })
      .eq('id', borrowId)

    if (borrowError) throw borrowError

    // อัปเดตสถานะอุปกรณ์
    const { error: assetError } = await supabase
      .from('assets')
      .update({ status: 'Available' })
      .eq('id', assetId)

    if (assetError) throw assetError

    return NextResponse.json({ success: true, message: 'บันทึกสำเร็จ' })
  } catch (error: any) {
    return NextResponse.json({ success: false, error: error.message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '../../../utils/supabase/server'

// 1. GET: ดึงประวัติการยืมทั้งหมด พร้อมดึงข้อมูล Assets และ Users มารวมด้วย (Join)
export async function GET() {
  const supabase = await createClient()

  const { data: borrows, error } = await supabase
    .from('borrows')
    .select(`
      id,
      doc_id,
      borrower_name,
      borrower_dept,
      phone,
      purpose,
      borrow_date,
      due_date,
      return_date,
      quantity,
      position,
      assets ( id, name, brand, contract_number, serial_number ),
      users ( id, full_name, emp_code )
    `)
    .order('borrow_date', { ascending: false })

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ success: true, data: borrows })
}

// 2. POST: บันทึกการยืมอุปกรณ์แบบรองรับระบบตะกร้า (วนลูปบันทึกทุกชิ้นที่ส่งมา)
export async function POST(request: Request) {
  const supabase = await createClient()

  try {
    const body = await request.json()
    
    // 👈 แกะค่าตามโครงสร้างที่หน้าบ้านส่งมาจริง
    const { 
      borrower_name,
      position, 
      borrower_purpose, 
      department, 
      phone, 
      return_date, 
      items // อาร์เรย์ของในตะกร้าครุภัณฑ์ [ { asset_id, quantity, ... }, ... ]
    } = body

    // Validation เบื้องต้น
    if (!items || !Array.isArray(items) || items.length === 0) {
      return NextResponse.json({ error: 'กรุณาเลือกครุภัณฑ์ลงตะกร้าอย่างน้อย 1 ชิ้น' }, { status: 400 })
    }
    if (!borrower_name) {
      return NextResponse.json({ error: 'กรุณาระบุชื่อผู้ยืม' }, { status: 400 })
    }
    if (!borrower_purpose) {
      return NextResponse.json({ error: 'กรุณาระบุวัตถุประสงค์การใช้งาน' }, { status: 400 })
    }

    const insertedBorrows = []

    // 🔄 วนลูปประมวลผลครุภัณฑ์ทีละชิ้นในตะกร้าสินค้า
    for (const item of items) {
      const currentAssetId = item.asset_id
      // ดึงค่าจำนวนชิ้นจากหน้าบ้านมาเตรียมไว้ ถ้าไม่มีให้มองเป็น 1 ชิ้นเดฟอลต์
      const currentQuantity = item.quantity || 1 

      // [ขั้นตอนเซฟตี้] เช็คก่อนว่าสินทรัพย์ชิ้นนี้ว่างจริงไหม
      const { data: assetCheck } = await supabase
        .from('assets')
        .select('status')
        .eq('id', currentAssetId)
        .single()

      if (assetCheck && (assetCheck.status === 'Borrowed' || assetCheck.status === 'กำลังใช้งาน')) {
        return NextResponse.json({ error: `อุปกรณ์ ${item.name || 'ชิ้นนี้'} ถูกยืมไปแล้ว ไม่สามารถยืมซ้ำได้` }, { status: 400 })
      }

      // บันทึกข้อมูลลงตาราง borrows ของชิ้นนั้น ๆ 
      const { data: borrowData, error: borrowError } = await supabase
        .from('borrows')
        .insert([
          {
            doc_id: null,
            user_id: null,
            asset_id: currentAssetId,
            borrower_name: borrower_name,
            position: position || null,
            borrower_dept: department || null, 
            phone: phone || null,            
            purpose: borrower_purpose || null,
            borrow_date: new Date().toISOString(),
            due_date: return_date ? new Date(return_date).toISOString() : null,
            quantity: currentQuantity // 🎯 บันทึกจำนวนชิ้นลงคอลัมน์ quantity ในตาราง borrows ตรงๆ เลยครับช่าง!
          }
        ])
        .select()

      if (borrowError) {
        return NextResponse.json({ error: `เกิดข้อผิดพลาดในการบันทึก: ${borrowError.message}` }, { status: 500 })
      }

      // เปลี่ยนสถานะในตาราง assets ให้เป็น 'Borrowed' ทันที
      await supabase
        .from('assets')
        .update({ status: 'Borrowed' })
        .eq('id', currentAssetId)

      if (borrowData && borrowData.length > 0) {
        insertedBorrows.push(borrowData[0])
      }
    }

    return NextResponse.json({ 
      success: true, 
      message: 'บันทึกคำขอยืมครุภัณฑ์ในตะกร้าทั้งหมดเรียบร้อยแล้ว', 
      data: insertedBorrows 
    }, { status: 201 })

  } catch (err) {
    return NextResponse.json({ error: 'รูปแบบโครงสร้างข้อมูลของหลังบ้านไม่ถูกต้อง' }, { status: 400 })
  }
}

import { createClient } from '@supabase/supabase-js';
import { NextResponse } from 'next/server';

export async function GET() {
  // 1. สร้าง Client ด้วย Service Role Key (ใช้สำหรับงานหลังบ้านเท่านั้น)
  // ห้ามใช้คีย์นี้ในหน้าบ้าน (Client Component) เด็ดขาด
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!, 
    process.env.SUPABASE_SERVICE_KEY! // ใส่คีย์นี้ในไฟล์ .env ของคุณ
  );

  // 2. ดึงรายการที่ยังไม่คืน และมี due_date
  const { data, error } = await supabase
    .from('borrows')
    .select('*, assets(*)')
    .is('return_date', null);

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }

  // 3. กรองรายการที่ถึงกำหนดแล้ว
  const today = new Date();
  const urgentList = (data || []).filter((item: any) => {
    if (!item.due_date) return false;
    const dueDate = new Date(item.due_date);
    // เช็คว่าเลยกำหนด หรือเหลือเวลาอีก 1 วัน
    const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays <= 1;
  });

  return NextResponse.json({ success: true, urgentList });
}

import { NextResponse } from 'next/server'
import { createClient } from '@/utils/supabase/server'

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const supabase = await createClient()
    const resolvedParams = await params
    const id = resolvedParams.id
    const body = await request.json()
    
    const { 
      status, 
      technician_name, 
      fix_detail, 
      service_price,
      repair_item_id,
      parts_usage // 💡 รายการอะไหล่ที่ใช้: [{ part_id, quantity }]
    } = body

    const repairId = parseInt(id)

    if (isNaN(repairId)) {
      return NextResponse.json({ success: false, error: 'ID ไม่ถูกต้อง' }, { status: 400 })
    }

    // 1. อัปเดตข้อมูลการซ่อมหลัก
    const repairUpdates: any = {
      status,
      technician_name,
      fix_detail,
      service_price
    }

    if (status === 'Completed') {
      repairUpdates.repair_finish = new Date().toISOString()
    }

    const { error: repairError } = await supabase
      .from('repairs')
      .update(repairUpdates)
      .eq('id', repairId)

    if (repairError) throw repairError

    // 2. จัดการเรื่องอะไหล่ (ถ้ามีการส่งมา)
    if (parts_usage && Array.isArray(parts_usage)) {
      for (const item of parts_usage) {
        // ดึงข้อมูลราคาและสต็อกปัจจุบัน
        const { data: partData } = await supabase
          .from('spare_parts')
          .select('stock_quantity, unit_price')
          .eq('id', item.part_id)
          .single()

        if (partData) {
          const quantityUsed = item.quantity
          const unitPrice = partData.unit_price || 0
          const priceExclVat = unitPrice * quantityUsed
          const vatPercent = 7.00
          const totalPrice = priceExclVat * (1 + vatPercent / 100)

          // บันทึกการใช้งานอะไหล่พร้อมรายละเอียดราคา
          const { error: usageError } = await supabase
            .from('repair_parts_usage')
            .insert([{
              repair_id: repairId,
              part_id: item.part_id,
              quantity_used: quantityUsed,
              price_excl_vat: priceExclVat,
              vat_percent: vatPercent,
              total_price: totalPrice
            }])
          
          if (usageError) throw usageError

          // ตัดสต็อกอะไหล่
          await supabase
            .from('spare_parts')
            .update({ stock_quantity: partData.stock_quantity - quantityUsed })
            .eq('id', item.part_id)
        }
      }
    }

    return NextResponse.json({ success: true })
  } catch (err: any) {
    console.error(`[PATCH /api/repairs] Error:`, err)
    return NextResponse.json({ success: false, error: err.message }, { status: 500 })
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const supabase = await createClient()
    const { id } = await params
    const repairId = parseInt(id)

    await supabase.from('repair_parts_usage').delete().eq('repair_id', repairId)
    await supabase.from('repair_items').delete().eq('repair_id', repairId)
    const { error } = await supabase.from('repairs').delete().eq('id', repairId)

    if (error) throw error
    return NextResponse.json({ success: true, message: 'ลบรายการสำเร็จ' })
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@/utils/supabase/server'

// 1. GET: ดึงรายการซ่อมทั้งหมด พร้อมข้อมูลจาก repair_items
export async function GET() {
  try {
    const supabase = await createClient()

    const { data: repairs, error } = await supabase
      .from('repairs')
      .select(`
        *,
        repair_items (
          *
        )
      `)
      .order('id', { ascending: false })

    if (error) {
      console.error('[GET /api/repairs] Supabase error:', error)
      return NextResponse.json({ success: false, error: error.message }, { status: 500 })
    }

    // 2. ดึงข้อมูลเอกสารที่เกี่ยวข้อง
    const { data: documents } = await supabase
      .from('documents')
      .select('*')
      .not('repair_id', 'is', null)

    // 3. ดึงข้อมูลค่าใช้จ่ายอะไหล่
    const { data: partCosts } = await supabase
      .from('repair_parts_usage')
      .select('repair_id, total_price, quantity_used')

    // แปรรูปข้อมูลให้แบน (Flatten) และแนบเอกสารพร้อมคำนวณราคา
    const formattedData = repairs.map((r: any) => {
      const repairDocs = documents?.filter((doc: any) => Number(doc.repair_id) === Number(r.id)) || []
      
      // คำนวณยอดรวมอะไหล่และจำนวน
      const repairParts = partCosts?.filter((p: any) => Number(p.repair_id) === Number(r.id)) || []
      const totalPartsCost = repairParts.reduce((sum: number, p: any) => sum + (Number(p.total_price) || 0), 0)
      const totalPartsQty = repairParts.reduce((sum: number, p: any) => sum + (Number(p.quantity_used) || 0), 0)

      return {
        ...r,
        item: r.repair_items?.[0] || null,
        documents: repairDocs,
        file_url: repairDocs.length > 0 ? repairDocs[0].file_url : null,
        total_parts_cost: totalPartsCost,
        total_parts_qty: totalPartsQty,
        grand_total: totalPartsCost + (Number(r.service_price) || 0)
      }
    })

    return NextResponse.json({ success: true, data: formattedData })
  } catch (err) {
    console.error('[GET /api/repairs] Exception:', err)
    return NextResponse.json({ success: false, error: String(err) }, { status: 500 })
  }
}

// 2. POST: เพิ่มรายการแจ้งซ่อมใหม่ (Manual Input ทั้งหมด)
export async function POST(request: Request) {
  try {
    const supabase = await createClient()
    const body = await request.json()
    
    const { 
      problem_detail, 
      requester_name, 
      requester_dept, 
      requester_phone,
      requester_position,
      requester_emp_code,
      manual_brand,
      manual_sn,
      assets_number,
      manual_contract,
      type_item
    } = body

    if (!manual_brand || !problem_detail) {
      return NextResponse.json({ success: false, error: 'กรุณาระบุชื่ออุปกรณ์และอาการเสีย' }, { status: 400 })
    }

    // 1. บันทึกลงตาราง repairs
    const { data: repairData, error: repairError } = await supabase
      .from('repairs')
      .insert([
        {
          requester_name,
          requester_dept,
          requester_phone,
          requester_position,
          requester_emp_code,
          status: 'Pending'
        }
      ])
      .select()

    if (repairError) throw repairError
    const newRepair = repairData[0]

    // 2. บันทึกลงตาราง repair_items
    const { error: itemError } = await supabase
      .from('repair_items')
      .insert([
        {
          repair_id: newRepair.id,
          problem_detail,
          manual_brand,
          manual_sn: manual_sn || null,
          assets_number: assets_number || null,
          manual_contract: manual_contract || null,
          type_item: type_item || null,
          status: 'Under Repair'
        }
      ])

    if (itemError) throw itemError

    return NextResponse.json({ success: true, data: newRepair }, { status: 201 })
  } catch (err: any) {
    console.error('[POST /api/repairs] Error:', err)
    return NextResponse.json({ success: false, error: err.message }, { status: 500 })
  }
}

