// app/borrows/request/generateBorrowPDF.ts
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";

interface Asset {
    id: number;
    asset_code: string;
    name: string;
    brand?: string;
    type?: string;
    serial_number?: string;
    contract_number?: string;
    quantity: number; 
}

interface BorrowData {
    borrower_name: string;
    borrower_purpose: string;
    department: string;
    phone: string;
    return_date: string;
    position?: string;
}

export const generateBorrowPDF = async (borrowData: BorrowData, items: Asset[]) => {
    const doc = new jsPDF({
        orientation: "p",
        unit: "mm",
        format: "a4",
    });

    const fontName = "THSarabunNew";

    const drawOuterBorder = () => {
        doc.setDrawColor(0, 0, 0);
        doc.setLineWidth(0.4);
        doc.rect(15, 15, 180, 267);
    };

    // 🔤 ระบบโหลดฟอนต์
    try {
        const response = await fetch("/api/font");
        if (!response.ok) throw new Error("ดึงฟอนต์ผ่าน API ล้มเหลว");
        const data = await response.json();
        doc.addFileToVFS("THSarabunNew.ttf", data.font);
        doc.addFont("THSarabunNew.ttf", fontName, "normal");
        doc.setFont(fontName);
    } catch (err) {
        console.error("ระบบฟอนต์ขัดข้อง:", err);
        alert("ไม่สามารถโหลดฟอนต์ภาษาไทยได้");
        return;
    }

    drawOuterBorder();

    // 1. ส่วนหัวเอกสาร
    doc.setFontSize(20);
    doc.text("เอกสารการขอยืมอุปกรณ์", 105, 24, { align: "center" });

    doc.rect(15, 29, 180, 8); 
    doc.setFontSize(14);
    doc.text(`วันที่ทำรายการ: ${new Date().toLocaleDateString("th-TH")}`, 19, 34);
    doc.text(`กำหนดส่งคืน: ${new Date(borrowData.return_date).toLocaleDateString("th-TH")}`, 115, 34);

    doc.rect(15, 40, 180, 24);
    doc.text(`ชื่อ-นามสกุล ผู้ขอยืม: ${borrowData.borrower_name}`, 19, 46);
    doc.text(`ตำแหน่ง: ${borrowData.position || "-"}`, 115, 46);
    doc.text(`แผนก/ฝ่าย/กอง: ${borrowData.department}`, 19, 53);
    doc.text(`เบอร์โทรศัพท์: ${borrowData.phone}`, 115, 53);
    doc.text(`วัตถุประสงค์: ${borrowData.borrower_purpose || "-"}`, 19, 60);

    // 2. ตารางรายการครุภัณฑ์
    const tableBodyData = items.map((item, index) => [
        index + 1, item.asset_code || "-", item.name || "-", item.brand || "-",
        `${item.quantity || 1} ชิ้น`, item.type || "-", item.serial_number || "-", item.contract_number || "-"
    ]);

    autoTable(doc, {
        startY: 69,
        head: [['ลำดับ', 'รหัสทรัพย์สิน', 'ชื่ออุปกรณ์', 'แบรนด์', 'จำนวน', 'ประเภท', 'Serial Number', 'เลขที่สัญญา']],
        body: tableBodyData,
        theme: 'grid',
        styles: { font: fontName, fontSize: 12, cellPadding: 3, valign: 'middle', lineColor: [0,0,0], lineWidth: 0.3 },
        headStyles: { fillColor: [245, 245, 245], textColor: [0, 0, 0], fontStyle: 'normal', halign: 'center' },
        columnStyles: { 0: { cellWidth: 10, halign: 'center' }, 1: { cellWidth: 25, halign: 'center' }, 2: { cellWidth: 40 }, 3: { cellWidth: 20, halign: 'center' }, 4: { cellWidth: 15, halign: 'center' }, 5: { cellWidth: 20, halign: 'center' }, 6: { cellWidth: 25, halign: 'center' }, 7: { cellWidth: 25, halign: 'center' } },
        margin: { left: 15, right: 15 },
        didDrawPage: (data) => { if (data.pageNumber > 1) { drawOuterBorder(); doc.setFont(fontName); } }
    });

    // 3. ส่วนลงนามลายเซ็น (แก้ไขให้ไม่ติดขอบกระดาษ)
    const finalTableY = (doc as any).lastAutoTable?.finalY || 188;
    const pageMargin = 20; 
    const sigBoxWidth = (210 - (pageMargin * 2) - 10) / 2;
    const sigBoxHeight = 30;
    const gapY = 5;

    let currentY = finalTableY + 10;
    if (currentY + (sigBoxHeight * 2) + 20 > doc.internal.pageSize.height - 15) {
        doc.addPage();
        drawOuterBorder();
        doc.setFont(fontName);
        currentY = 25;
    }

    const drawSignatureBox = (x: number, y: number, label: string) => {
        doc.rect(x, y, sigBoxWidth, sigBoxHeight);
        doc.text(`ลงชื่อ......................................${label}`, x + 7, y + 10);
        doc.text("(..........................................)", x + 12, y + 20);
        doc.text("วันที่......./......./.......", x + 18, y + 27);
    };

    drawSignatureBox(pageMargin, currentY, "ผู้ขอยืม");
    drawSignatureBox(pageMargin + sigBoxWidth + 10, currentY, "ผู้อนุมัติ");
    drawSignatureBox(pageMargin, currentY + sigBoxHeight + gapY, "ผู้ส่งคืน");
    drawSignatureBox(pageMargin + sigBoxWidth + 10, currentY + sigBoxHeight + gapY, "ผู้รับคืน");

    doc.save(`ใบยืมครุภัณฑ์_${borrowData.borrower_name}_${Date.now()}.pdf`);
};

"use strict";
"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import Swal from "sweetalert2";
// 📄 นำเข้าฟังก์ชันสร้างเอกสาร PDF ที่อยู่ข้างกันเข้ามาใช้งาน
import { generateBorrowPDF } from "./generateBorrowPDF";

interface Asset {
    id: string;
    asset_code: string;
    borrower_purpose: string;
    name: string;
    brand: string;
    type: string;
    serial_number: string;
    contract_number: string;
    status: string; // ว่าง, กำลังใช้งาน, ชำรุด
}

// 🎯 โครงสร้างไอเทมในตะกร้า (ขยายเพิ่มฟิลด์ quantity เพื่อเก็บจำนวนชิ้น)
interface CartItem extends Asset {
    quantity: number;
}

// 🗺️ ออบเจกต์แมปไอคอนตามประเภทอุปกรณ์ สำหรับธีมดาร์ก
const ASSET_TYPES: { [key: string]: string } = {
    Notebook: "💻",
    Tablet: "📱",
    Desktop: "🖥️",
    Monitor: "📺",
    Projector: "📹",
    Printer: "🖨️",
    Scanner: "📑",
    UPS: "🔋",
    network: "🌐",
    Camera: "📷",
    Other: "🛠️",
    microphone: "🎤",
    Signalcable: "🔌",
    "Wiring set": "🔌"
};

export default function BorrowRequestPage() {
    const [assets, setAssets] = useState<Asset[]>([]);
    const [isMounted, setIsMounted] = useState(false);

    const [searchTerm, setSearchTerm] = useState("");
    const [cart, setCart] = useState<CartItem[]>([]); // 🎯 ปรับ State รองรับ CartItem ชนิดใหม่ที่มีจำนวนชิ้น
    const [loading, setLoading] = useState(true);

    // ข้อมูลฟอร์มผู้ยืม
    const [borrowerPurpose, setBorrowerPurpose] = useState("");
    const [borrowerName, setBorrowerName] = useState("");
    const [position, setPosition] = useState(""); // 🛠️ State สำหรับตำแหน่งงาน
    const [department, setDepartment] = useState("");
    const [phone, setPhone] = useState("");
    const [returnDate, setReturnDate] = useState("");

    // 🎯 State สำหรับระบบ Pagination (แบ่งตารางหน้าละ 5 รายการ)
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 5;

    // 1. ดึงข้อมูลครุภัณฑ์ทั้งหมดจากหลังบ้าน
    useEffect(() => {
        fetch("/api/assets")
            .then((res) => res.json())
            .then((responseBody) => {
                const assetsArray = Array.isArray(responseBody.data) ? responseBody.data : [];
                setAssets(assetsArray);
                setLoading(false);
                setIsMounted(true);
            })
            .catch((err) => {
                console.error("Error fetching assets:", err);
                loading && setLoading(false);
                setIsMounted(true);
            });
    }, [loading]);

    // 2. ฟังก์ชันเพิ่มของเข้าตะกร้า (ถ้าซ้ำชิ้นเดิมจะไปบวกเพิ่มจำนวนที่หางตะกร้า)
    const addToCart = (asset: Asset) => {
        setCart((prevCart) => {
            const existing = prevCart.find((item) => item.id === asset.id);
            if (existing) {
                Swal.fire({ icon: "success", title: "เพิ่มจำนวนอุปกรณ์ในตะกร้าแล้ว", timer: 1000, showConfirmButton: false });
                return prevCart.map((item) =>
                    item.id === asset.id ? { ...item, quantity: item.quantity + 1 } : item
                );
            }
            Swal.fire({ icon: "success", title: "เพิ่มลงตะกร้าสำเร็จ", timer: 1000, showConfirmButton: false });
            return [...prevCart, { ...asset, quantity: 1 }];
        });
    };

    // 🎯 ฟังก์ชันเพิ่ม/ลดจำนวนชิ้นอุปกรณ์ในหน้าตะกร้าโดยตรง
    const updateQuantity = (id: string, newQty: number) => {
        if (newQty < 1) return; // ล็อกไม่ให้ลดจนติดลบหรือเป็น 0 (ถ้าจะเอาออกให้กดรูปถังขยะ)
        setCart((prevCart) =>
            prevCart.map((item) => (item.id === id ? { ...item, quantity: newQty } : item))
        );
    };

    // 3. ฟังก์ชันลบของออกจากตะกร้า
    const removeFromCart = (id: string) => {
        setCart(cart.filter((item) => item.id !== id));
    };

    // 🔍 4. ตรรกะการกรองค้นหา และแยกประเภทออกเป็น 2 ตาราง
    const searchLower = searchTerm.toLowerCase().trim();

    const searchedAssets = assets.filter((asset) => {
        const name = asset?.name ? asset.name.toLowerCase() : "";
        const brand = asset?.brand ? asset.brand.toLowerCase() : "";
        const code = asset?.asset_code ? asset.asset_code.toLowerCase() : "";
        const type = asset?.type ? asset.type.toLowerCase() : "";
        const serial = asset?.serial_number ? asset.serial_number.toLowerCase() : "";
        return name.includes(searchLower) || code.includes(searchLower) || type.includes(searchLower) || serial.includes(searchLower) || brand.includes(searchLower);
    });

    // 🟢 ตารางบน: ครุภัณฑ์ที่พร้อมให้ยืม (สถานะ ว่าง หรือ Available)
    const availableAssets = searchedAssets.filter(
        (item) => item.status === "ว่าง" || item.status === "Available"
    );

    // 🎯 คำนวณตัดแบ่งข้อมูลครุภัณฑ์ที่พร้อมยืม ให้เหลือแสดงหน้าละ 5 รายการ
    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentAvailableAssets = availableAssets.slice(indexOfFirstItem, indexOfLastItem);
    const totalPages = Math.ceil(availableAssets.length / itemsPerPage);

    // 🔒 ตารางล่าง: ครุภัณฑ์ที่ถูกยืมอยู่ หรือไม่ว่างชั่วคราว
    const borrowedAssets = searchedAssets.filter(
        (item) => item.status !== "ว่าง" && item.status !== "Available"
    );

    // 5. ส่งคำขอยืมชุดใหญ่ไปที่หลังบ้าน
    const handleSubmitBorrow = async (e: React.FormEvent) => {
        e.preventDefault();

        if (cart.length === 0) {
            Swal.fire({ icon: "error", title: "กรุณาเลือกอุปกรณ์ลงตะกร้าอย่างน้อย 1 ชิ้น" });
            return;
        }

        Swal.fire({
            title: "กำลังบันทึกข้อมูล...",
            allowOutsideClick: false,
            didOpen: () => { Swal.showLoading(); }
        });

        try {
            const response = await fetch("/api/borrows", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    borrower_name: borrowerName,
                    position: position, // 🛠️ ส่งค่าตำแหน่งไปยัง API
                    borrower_purpose: borrowerPurpose,
                    department: department,
                    phone: phone,
                    return_date: returnDate,
                    items: cart.map((item) => ({
                        asset_id: item.id,
                        asset_name: item.name,
                        asset_brand: item.brand,
                        asset_type: item.type,
                        serial_number: item.serial_number,
                        contract_number: item.contract_number,
                        quantity: item.quantity // 🎯 แนบจำนวนชิ้นแต่ละไอเทมส่งไปหลังบ้าน
                    }))
                })
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                throw new Error(errorData.error || errorData.message || `Server ตอบกลับด้วยรหัสสถานะ ${response.status}`);
            }

            // 📄 เรียกใช้ไฟล์ Utility เพื่อสั่งสร้างและดาวน์โหลดเอกสาร PDF ทันที
            await generateBorrowPDF(
                {
                    borrower_name: borrowerName,
                    position: position, // 🛠️ ส่งค่าตำแหน่งไปพ่นใน PDF
                    borrower_purpose: borrowerPurpose,
                    department: department,
                    phone: phone,
                    return_date: returnDate
                },
                cart.map(item => ({
                    id: Number(item.id),
                    asset_code: item.asset_code,
                    name: item.name,
                    brand: item.brand,
                    type: item.type,
                    serial_number: item.serial_number,
                    contract_number: item.contract_number,
                    quantity: item.quantity // 🎯 แนบจำนวนชิ้นส่งไปจัดสไตล์พ่นในไฟล์ PDF
                }))
            );

            Swal.fire({
                icon: "success",
                title: "ส่งคำขอยืมสำเร็จแล้ว!",
                text: "ระบบได้บันทึกข้อมูลและกำลังดาวน์โหลดใบอนุมัติยืม PDF",
                confirmButtonColor: "#3b82f6"
            }).then(() => {
                setCart([]);
                setBorrowerName("");
                setPosition(""); // 🛠️ ล้างค่าหลังส่งฟอร์มสำเร็จ
                setDepartment("");
                setPhone("");
                setReturnDate("");
                window.location.reload();
            });

        } catch (error: any) {
            console.error(error);
            Swal.fire({
                icon: "error",
                title: "เกิดข้อผิดพลาดในการบันทึก",
                text: error.message || "กรุณาตรวจสอบการเชื่อมต่อระบบฐานข้อมูล",
                confirmButtonColor: "#ef4444"
            });
        }
    };

    if (!isMounted) return null;

    return (
        <main className="min-h-screen bg-slate-950 text-slate-100 p-4 md:p-8 font-sans">
            <div className="max-w-7xl mx-auto">

                {/* ส่วนหัวหน้าจอ */}
                <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8 pb-4 border-b border-slate-800">
                    <div>
                        <h1 className="text-3xl font-extrabold text-white flex items-center gap-3">
                            🛒 ระบบส่งคำขอยืมอุปกรณ์
                        </h1>
                        <p className="text-slate-400 text-sm mt-1">เลือกอุปกรณ์ที่ต้องการใส่ตะกร้า จากนั้นกรอกข้อมูลยืมด้านขวาได้เลย</p>
                    </div>
                    <Link href="/" className="mt-4 md:mt-0 text-sm bg-slate-800 hover:bg-slate-700 text-slate-300 px-4 py-2 rounded-xl transition-colors border border-slate-700">
                        ← กลับหน้าหลัก
                    </Link>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                    {/* ================= ฝั่งซ้าย: โซนตารางข้อมูลครุภัณฑ์ ================= */}
                    <div className="lg:col-span-2 space-y-6">

                        {/* 🟢 ตารางที่ 1: อุปกรณ์ที่พร้อมให้ยืม */}
                        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
                            <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                                🟢 อุปกรณ์ที่พร้อมให้ยืม ({availableAssets.length} รายการ)
                            </h2>

                            {/* ช่องค้นหา */}
                            <div className="mb-4">
                                <input
                                    type="text"
                                    placeholder="🔍 ค้นหาด้วย ชื่ออุปกรณ์, แบรนด์, ประเภท, รหัส หรือ Serial Number..."
                                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-slate-100 placeholder-slate-500 focus:outline-none focus:border-blue-500 text-sm transition-colors"
                                    value={searchTerm}
                                    onChange={(e) => {
                                        setSearchTerm(e.target.value);
                                        setCurrentPage(1); // ดีดกลับหน้า 1 อัตโนมัติป้องกันบั๊กหน้าว่าง
                                    }}
                                />
                            </div>

                            {/* ตารางข้อมูลที่พร้อมยืม */}
                            {loading ? (
                                <div className="text-center py-8 text-slate-400">กำลังโหลดรายการอุปกรณ์...</div>
                            ) : availableAssets.length === 0 ? (
                                <div className="text-center py-8 text-slate-500">❌ ไม่พบข้อมูลอุปกรณ์ที่พร้อมยืม</div>
                            ) : (
                                <>
                                    <div className="overflow-x-auto">
                                        <table className="w-full text-left text-sm">
                                            <thead>
                                                <tr className="border-b border-slate-800 text-slate-400 font-semibold bg-slate-950/40">
                                                    <th className="p-3">ชื่ออุปกรณ์</th>
                                                    <th className="p-3">แบรนด์</th>
                                                    <th className="p-3">ประเภท</th>
                                                    <th className="p-3">รหัส/Serial</th>
                                                    <th className="p-3">รหัสทรัพย์สิน</th>
                                                    <th className="p-3">เลขที่สัญญา</th>
                                                    <th className="p-3 text-center">การกระทำ</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-800/60">
                                                {currentAvailableAssets.map((asset) => {
                                                    const assetType = asset.type || "Other";
                                                    const typeIcon = ASSET_TYPES[assetType] || "🛠️";

                                                    return (
                                                        <tr key={asset.id} className="hover:bg-slate-800/30 transition-colors">
                                                            <td className="p-3">
                                                                <div className="text-white font-semibold">{asset.name || "-"}</div>
                                                            </td>
                                                            <td className="p-3 text-slate-300 font-mono text-xs">
                                                                {asset.brand || "-"}
                                                            </td>
                                                            <td className="p-3">
                                                                <span className="px-2.5 py-1 bg-slate-950 text-slate-300 border border-slate-800 rounded-lg text-xs font-medium inline-flex items-center gap-1.5">
                                                                    {typeIcon} {assetType}
                                                                </span>
                                                            </td>
                                                            <td className="p-3 text-slate-300 font-mono text-xs">
                                                                {asset.serial_number || "-"}
                                                            </td>
                                                            <td className="p-3 text-slate-300 font-mono text-xs">
                                                                {asset.asset_code || "-"}
                                                            </td>
                                                            <td className="p-3 text-xs font-mono text-slate-400">
                                                                {asset.contract_number || "-"}
                                                            </td>
                                                            <td className="p-3 text-center">
                                                                <button
                                                                    type="button"
                                                                    onClick={() => addToCart(asset)}
                                                                    className="bg-blue-600 hover:bg-blue-500 text-white px-3 py-1.5 rounded-lg font-medium text-xs transition-colors flex items-center gap-1 mx-auto shadow-lg shadow-blue-900/20"
                                                                >
                                                                    <span>+</span> ใส่ตะกร้า
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    );
                                                })}
                                            </tbody>
                                        </table>
                                    </div>

                                    {/* 🎯 บล็อกชุดปุ่มกด Pagination ใต้ตาราง Available */}
                                    {totalPages > 1 && (
                                        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mt-4 pt-4 border-t border-slate-800/60 gap-3">
                                            <p className="text-xs text-slate-500 text-center sm:text-left">
                                                แสดง {indexOfFirstItem + 1} ถึง {Math.min(indexOfLastItem, availableAssets.length)} จากทั้งหมด {availableAssets.length} รายการ
                                            </p>
                                            <div className="flex items-center justify-center space-x-1.5">
                                                <button
                                                    type="button"
                                                    disabled={currentPage === 1}
                                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                                    className="px-2.5 py-1.5 rounded-lg text-xs font-medium bg-slate-950 border border-slate-800 text-slate-400 hover:text-white disabled:opacity-40 disabled:hover:text-slate-400 transition-colors"
                                                >
                                                    ก่อนหน้า
                                                </button>

                                                {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                                                    <button
                                                        key={page}
                                                        type="button"
                                                        onClick={() => setCurrentPage(page)}
                                                        className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${currentPage === page
                                                                ? "bg-blue-600 text-white"
                                                                : "bg-slate-950 border border-slate-800 text-slate-400 hover:text-white"
                                                            }`}
                                                    >
                                                        {page}
                                                    </button>
                                                ))}

                                                <button
                                                    type="button"
                                                    disabled={currentPage === totalPages}
                                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                                    className="px-2.5 py-1.5 rounded-lg text-xs font-medium bg-slate-950 border border-slate-800 text-slate-400 hover:text-white disabled:opacity-40 disabled:hover:text-slate-400 transition-colors"
                                                >
                                                    ถัดไป
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </>
                            )}
                        </div>

                        {/* 🔒 ตารางที่ 2: ครุภัณฑ์ที่อยู่ระหว่างการยืมหรือชำรุด */}
                        {!loading && (
                            <div className="bg-slate-900/60 border border-slate-800/80 rounded-2xl p-6 shadow-xl">
                                <h2 className="text-sm font-bold text-slate-400 mb-2 flex items-center gap-2">
                                    🔒 อุปกรณ์ที่ไม่ว่างชั่วคราว ({borrowedAssets.length} รายการ)
                                </h2>
                                <p className="text-xs text-slate-600 mb-4">อุปกรณ์กลุ่มนี้อยู่ระหว่างการใช้งานหรือชำรุด จะเปิดให้ยืมเมื่อได้รับการส่งคืนและปรับสถานะ</p>

                                {borrowedAssets.length === 0 ? (
                                    <div className="text-center py-6 text-slate-600 text-xs">✨ ไม่มีอุปกรณ์ถูกยืมอยู่ ทุกชิ้นพร้อมใช้งานทั้งหมด</div>
                                ) : (
                                    <div className="overflow-x-auto">
                                        <table className="w-full text-left text-xs sm:text-sm">
                                            <thead>
                                                <tr className="border-b border-slate-800/60 text-slate-500 font-medium">
                                                    <th className="p-3">ชื่ออุปกรณ์</th>
                                                    <th className="p-3">แบรนด์</th>
                                                    <th className="p-3">ประเภท</th>
                                                    <th className="p-3">รหัส/Serial</th>
                                                    <th className="p-3">รหัสทรัพย์สิน</th>
                                                    <th className="p-3">เลขที่สัญญา</th>
                                                    <th className="p-3 text-center">สถานะ</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-800/30 text-slate-400">
                                                {borrowedAssets.map((asset) => {
                                                    const assetType = asset.type || "Other";
                                                    const typeIcon = ASSET_TYPES[assetType] || "🛠️";
                                                    const isBroken = asset.status === "ชำรุด";

                                                    return (
                                                        <tr key={asset.id} className="hover:bg-slate-800/10 transition-colors opacity-70">
                                                            <td className="p-3">
                                                                <div className="text-slate-400 font-medium">{asset.name || "-"}</div>
                                                            </td>
                                                            <td className="p-3 text-slate-500 font-mono text-xs">
                                                                {asset.brand || "-"}
                                                            </td>
                                                            <td className="p-3">
                                                                <span className="px-2 py-0.5 bg-slate-950/50 text-slate-500 border border-slate-900 rounded text-xs inline-flex items-center gap-1">
                                                                    {typeIcon} {assetType}
                                                                </span>
                                                            </td>
                                                            <td className="p-3 text-slate-500 font-mono text-xs">
                                                                {asset.serial_number || "-"}
                                                            </td>
                                                            <td className="p-3 text-slate-500 font-mono text-xs">
                                                                {asset.asset_code || "-"}
                                                            </td>
                                                            <td className="p-3 text-xs font-mono text-slate-600">
                                                                {asset.contract_number || "-"}
                                                            </td>
                                                            <td className="p-3 text-center">
                                                                <span className={`inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-semibold border ${isBroken
                                                                        ? "bg-red-950/40 text-red-400 border-red-900/40"
                                                                        : "bg-amber-950/40 text-amber-400 border-amber-900/40"
                                                                    }`}>
                                                                    ● {asset.status || "ถูกยืมอยู่"}
                                                                </span>
                                                            </td>
                                                        </tr>
                                                    );
                                                })}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* ================= ฝั่งขวา: ตะกร้าและฟอร์มส่งข้อมูล ================= */}
                    <div className="space-y-6">
                        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl sticky top-6">
                            <h2 className="text-xl font-bold text-white mb-4 flex items-center justify-between">
                                📋 รายการใบยืมของคุณ
                                <span className="text-xs bg-blue-500/10 text-blue-400 px-2.5 py-1 rounded-full border border-blue-500/20">
                                    {cart.reduce((sum, item) => sum + item.quantity, 0)} ชิ้น
                                </span>
                            </h2>

                            {/* รายการของในตะกร้า */}
                            <div className="mb-6 space-y-2 max-h-48 overflow-y-auto pr-1">
                                {cart.length === 0 ? (
                                    <div className="text-center py-6 border-2 border-dashed border-slate-800 rounded-xl text-slate-500 text-xs">
                                        🛒 ตะกร้ายังว่างเปล่า <br />กรุณากดเลือกอุปกรณ์จากฝั่งซ้าย
                                    </div>
                                ) : (
                                    cart.map((item) => (
                                        <div key={item.id} className="bg-slate-950 border border-slate-800 rounded-xl p-3 flex items-center justify-between text-xs hover:border-slate-700 transition-colors gap-2">
                                            <div className="truncate max-w-[50%]">
                                                <div className="font-bold text-white truncate">{item.name}</div>
                                                <div className="text-slate-500 font-mono mt-0.5">{item.asset_code}</div>
                                            </div>

                                            {/* ปุ่มเพิ่ม-ลดจำนวนชิ้นของอุปกรณ์แต่ละชิ้น */}
                                            <div className="flex items-center gap-1.5 bg-slate-900 border border-slate-800 rounded-lg p-1 shrink-0">
                                                <button
                                                    type="button"
                                                    onClick={() => updateQuantity(item.id, item.quantity - 1)}
                                                    className="w-5 h-5 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-800 rounded transition-colors font-bold text-sm"
                                                >
                                                    -
                                                </button>
                                                <span className="text-white font-bold w-5 text-center text-xs">{item.quantity}</span>
                                                <button
                                                    type="button"
                                                    onClick={() => updateQuantity(item.id, item.quantity + 1)}
                                                    className="w-5 h-5 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-800 rounded transition-colors font-bold text-sm"
                                                >
                                                    +
                                                </button>
                                            </div>

                                            <button
                                                type="button"
                                                onClick={() => removeFromCart(item.id)}
                                                className="text-red-400 hover:text-red-300 font-bold p-1 hover:bg-red-500/10 rounded-lg transition-colors shrink-0"
                                            >
                                                🗑️
                                            </button>
                                        </div>
                                    ))
                                )}
                            </div>

                            {/* ฟอร์มกรอกข้อมูลผู้ยืม */}
                            <form onSubmit={handleSubmitBorrow} className="space-y-4 border-t border-slate-800 pt-4">
                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">วัตถุประสงค์การใช้งาน</label>
                                    <input
                                        type="text"
                                        required
                                        placeholder="ระบุวัตถุประสงค์การใช้งาน"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={borrowerPurpose}
                                        onChange={(e) => setBorrowerPurpose(e.target.value)}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">ชื่อ-นามสกุล ผู้ยืม</label>
                                    <input
                                        type="text"
                                        required
                                        placeholder="ระบุชื่อจริงของคุณ"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={borrowerName}
                                        onChange={(e) => setBorrowerName(e.target.value)}
                                    />
                                </div>

                                {/* 🛠️ เพิ่มฟิลด์ตำแหน่งงาน (Job Position) ตรงนี้ */}
                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">ตำแหน่งงาน (Position)</label>
                                    <input
                                        type="text"
                                        required
                                        placeholder="เช่น Engineer, Technician, Admin"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={position}
                                        onChange={(e) => setPosition(e.target.value)}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">แผนก/ฝ่าย (Department)</label>
                                    <input
                                        type="text"
                                        required
                                        placeholder="ระบุฝ่ายหรือแผนกสังกัด"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={department}
                                        onChange={(e) => setDepartment(e.target.value)}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">เบอร์โทรศัพท์ติดต่อ</label>
                                    <input
                                        type="tel"
                                        required
                                        placeholder="ระบุเบอร์โทรศัพท์ 10 หลัก"
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={phone}
                                        onChange={(e) => setPhone(e.target.value)}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-semibold text-slate-400 mb-1.5">วันกำหนดส่งคืนอุปกรณ์</label>
                                    <input
                                        type="date"
                                        required
                                        className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-slate-100 text-sm focus:outline-none focus:border-blue-500"
                                        value={returnDate}
                                        onChange={(e) => setReturnDate(e.target.value)}
                                    />
                                </div>

                                <button
                                    type="submit"
                                    className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-4 rounded-xl text-sm transition-colors shadow-lg shadow-blue-900/30 mt-2"
                                >
                                    💾 ยืนยันคำขอยืมและพิมพ์ใบอนุมัติ
                                </button>
                            </form>
                        </div>
                    </div>

                </div>
            </div>
        </main>
    );
}

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";

interface RepairData {
    id: number;
    repair_date: string;
    repair_finish?: string;
    requester_name: string;
    requester_dept: string;
    requester_phone?: string;
    requester_position?: string;
    status: string;
    technician_name?: string;
    fix_detail?: string;
    item?: {
        manual_brand: string;
        assets_number?: string;
        manual_sn?: string;
        problem_detail: string;
        type_item?: string;
        manual_contract?: string;
    };
    parts?: Array<{
        part_name: string;
        quantity: number;
    }>;
}

export const generateRepairPDF = async (repair: RepairData) => {
    const doc = new jsPDF({
        orientation: "p",
        unit: "mm",
        format: "a4",
    });

    const fontName = "THSarabunNew";

    const drawOuterBorder = () => {
        doc.setDrawColor(0, 0, 0);
        doc.setLineWidth(0.4);
        doc.rect(15, 15, 180, 267);
    };

    // 🔤 ระบบโหลดฟอนต์
    try {
        const response = await fetch("/api/font");
        if (!response.ok) throw new Error("ดึงฟอนต์ผ่าน API ล้มเหลว");
        const data = await response.json();
        doc.addFileToVFS("THSarabunNew.ttf", data.font);
        doc.addFont("THSarabunNew.ttf", fontName, "normal");
        doc.setFont(fontName);
    } catch (err) {
        console.error("ระบบฟอนต์ขัดข้อง:", err);
        alert("ไม่สามารถโหลดฟอนต์ภาษาไทยได้");
        return;
    }

    drawOuterBorder();

    // 1. ส่วนหัวเอกสาร
    doc.setFontSize(22);
    doc.text("ใบแจ้งซ่อม / บันทึกการซ่อม", 105, 25, { align: "center" });
    doc.setFontSize(12);
    doc.text(`เลขที่ใบแจ้งซ่อม: RE-${repair.id.toString().padStart(5, '0')}`, 190, 20, { align: "right" });

    // 2. ข้อมูลผู้แจ้งซ่อม
    doc.rect(15, 32, 180, 8, 'F');
    doc.setFillColor(240, 240, 240);
    doc.rect(15, 32, 180, 8);
    doc.setFontSize(14);
    doc.text("ข้อมูลผู้แจ้งซ่อม", 20, 37.5);

    doc.rect(15, 40, 180, 25);
    doc.text(`ชื่อ-นามสกุล: ${repair.requester_name}`, 20, 47);
    doc.text(`หน่วยงาน/แผนก: ${repair.requester_dept}`, 110, 47);
    doc.text(`ตำแหน่ง: ${repair.requester_position || "-"}`, 20, 54);
    doc.text(`เบอร์โทรศัพท์: ${repair.requester_phone || "-"}`, 110, 54);
    doc.text(`วันที่แจ้งซ่อม: ${new Date(repair.repair_date).toLocaleDateString("th-TH")}`, 20, 61);

    // 3. รายละเอียดอุปกรณ์
    doc.rect(15, 70, 180, 8);
    doc.text("รายละเอียดอุปกรณ์", 20, 75.5);

    doc.rect(15, 78, 180, 32);
    doc.text(`อุปกรณ์: ${repair.item?.manual_brand || "-"}`, 20, 85);
    doc.text(`ประเภท: ${repair.item?.type_item || "-"}`, 110, 85);
    doc.text(`เลขครุภัณฑ์: ${repair.item?.assets_number || "-"}`, 20, 92);
    doc.text(`Serial Number: ${repair.item?.manual_sn || "-"}`, 110, 92);
    doc.text(`เลขที่สัญญา: ${repair.item?.manual_contract || "-"}`, 20, 99);
    doc.text(`สถานะปัจจุบัน: ${repair.status}`, 110, 99);
    doc.text(`อาการเสียที่แจ้ง: ${repair.item?.problem_detail || "-"}`, 20, 106);

    // 4. บันทึกการแก้ไข (สำหรับช่าง)
    doc.rect(15, 115, 180, 8);
    doc.text("บันทึกการแก้ไขและการดำเนินการ (สำหรับช่าง)", 20, 120.5);

    doc.rect(15, 123, 180, 45);
    doc.text(`ช่างผู้รับผิดชอบ: ${repair.technician_name || "-"}`, 20, 130);
    doc.text(`วันที่ซ่อมเสร็จ: ${repair.repair_finish ? new Date(repair.repair_finish).toLocaleDateString("th-TH") : "-"}`, 110, 130);
    
    doc.text("รายละเอียดการแก้ไข:", 20, 137);
    const splitFix = doc.splitTextToSize(repair.fix_detail || "-", 170);
    doc.text(splitFix, 25, 144);

    // 4.5 รายการอะไหล่ (ถ้ามี)
    let currentY = 175;
    if (repair.parts && repair.parts.length > 0) {
        autoTable(doc, {
            startY: 172,
            head: [['ลำดับ', 'รายการอะไหล่ที่เบิกใช้', 'จำนวน']],
            body: repair.parts.map((p, i) => [i + 1, p.part_name, `${p.quantity} ชิ้น`]),
            theme: 'grid',
            styles: { font: fontName, fontSize: 10, cellPadding: 2 },
            headStyles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold' },
            columnStyles: { 0: { cellWidth: 15, halign: 'center' }, 2: { cellWidth: 30, halign: 'center' } },
            margin: { left: 15, right: 15 },
        });
        currentY = (doc as any).lastAutoTable.finalY + 10;
    }

    // 5. ส่วนลงนาม
    const sigY = Math.max(currentY, 215);
    const sigBoxWidth = 80;
    const sigBoxHeight = 35;

    // ฝั่งผู้แจ้งซ่อม
    doc.rect(20, sigY, sigBoxWidth, sigBoxHeight);
    doc.text("ผู้แจ้งซ่อม / ผู้รับอุปกรณ์คืน", 20 + sigBoxWidth/2, sigY + 7, { align: "center" });
    doc.text("ลงชื่อ..................................................", 20 + sigBoxWidth/2, sigY + 20, { align: "center" });
    doc.text("ลงชื่อ..................................................", 20 + sigBoxWidth/2, sigY + 20, { align: "center" });
    doc.text("วันที่......../......../........", 20 + sigBoxWidth/2, sigY + 33, { align: "center" });

    // ฝั่งช่าง
    doc.rect(110, sigY, sigBoxWidth, sigBoxHeight);
    doc.text("ผู้ดำเนินการ / ผู้ส่งคืน", 110 + sigBoxWidth/2, sigY + 7, { align: "center" });
    doc.text("ลงชื่อ..................................................", 110 + sigBoxWidth/2, sigY + 20, { align: "center" });
    doc.text("ลงชื่อ..................................................", 20 + sigBoxWidth/2, sigY + 20, { align: "center" });
    doc.text("วันที่......../......../........", 110 + sigBoxWidth/2, sigY + 33, { align: "center" });

    // Footer
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    doc.text(`เอกสารนี้พิมพ์โดยระบบบริหารจัดการทรัพย์สิน เมื่อวันที่ ${new Date().toLocaleString("th-TH")}`, 105, 275, { align: "center" });

    doc.save(`ใบแจ้งซ่อม_RE-${repair.id}_${repair.requester_name}.pdf`);
};

'use client'

import { useState, useEffect, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import Link from 'next/link'
import RepairTable from '@/components/RepairTable'
import RepairManageTable from '@/components/RepairManageTable'
import SparePartsTable from '@/components/SparePartsTable'

function RepairsContent() {
  const searchParams = useSearchParams()
  const initialTab = searchParams.get('tab') || 'history'
  const [activeTab, setActiveTab] = useState(initialTab)

  useEffect(() => {
    const tab = searchParams.get('tab')
    if (tab) setActiveTab(tab)
  }, [searchParams])

  return (
    <div className="max-w-7xl mx-auto">
        
        {/* Navigation */}
        <div className="mb-8 flex items-center justify-between">
          <div className="flex items-center gap-2 text-sm text-slate-500">
            <Link href="/" className="hover:text-blue-600 transition-colors">Portal</Link>
            <span>/</span>
            <span className="text-slate-900 font-medium">ระบบบริหารงานซ่อม & อะไหล่</span>
          </div>
          <Link href="/" className="text-sm bg-white border border-slate-200 px-4 py-2 rounded-xl hover:bg-slate-50 transition-colors shadow-sm font-medium flex items-center gap-2">
            🏠 <span>กลับหน้าหลัก Portal</span>
          </Link>
        </div>

        {/* Header Section */}
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 mb-8 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center gap-6">
            <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-inner border transition-all duration-500 
              ${activeTab === 'manage' ? 'bg-slate-900 border-slate-800 text-white' : 
                activeTab === 'stock' ? 'bg-emerald-100 border-emerald-200 text-emerald-700' : 'bg-amber-100 border-amber-200'}`}>
              {activeTab === 'manage' ? '⚙️' : activeTab === 'stock' ? '📦' : '📜'}
            </div>
            <div>
              <h1 className="text-2xl font-bold text-slate-900">
                {activeTab === 'manage' ? 'Technician Center' : activeTab === 'stock' ? 'Inventory Management' : 'Repair History'}
              </h1>
              <p className="text-slate-500 text-sm mt-1">
                {activeTab === 'manage' 
                  ? 'พื้นที่สำหรับช่าง: อัปเดตสถานะงานซ่อมและบันทึกรายละเอียดการแก้ไข' 
                  : activeTab === 'stock'
                  ? 'จัดการคลังอะไหล่: ตรวจสอบจำนวนคงเหลือและเพิ่มรายการอะไหล่ใหม่'
                  : 'ระบบบันทึกประวัติการซ่อมแซมครุภัณฑ์ ติดตามสถานะ และรายละเอียดงานซ่อม'}
              </p>
            </div>
          </div>
          
          {/* Tab Switcher */}
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
            <button
              onClick={() => setActiveTab('history')}
              className={`flex items-center gap-2 px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'history' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              📜 ประวัติ
            </button>
            <button
              onClick={() => setActiveTab('manage')}
              className={`flex items-center gap-2 px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'manage' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}
            >
              🛠️ จัดการงาน
            </button>
            <button
              onClick={() => setActiveTab('stock')}
              className={`flex items-center gap-2 px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'stock' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}
            >
              📦 สต็อกอะไหล่
            </button>
          </div>
        </div>

        {/* Dynamic Content */}
        <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden min-h-[500px]">
          {activeTab === 'history' && (
            <div className="animate-in fade-in duration-500">
              <RepairTable />
            </div>
          )}
          {activeTab === 'manage' && (
            <div className="animate-in fade-in duration-500">
              <RepairManageTable />
            </div>
          )}
          {activeTab === 'stock' && (
            <div className="animate-in fade-in duration-500">
              <SparePartsTable />
            </div>
          )}
        </div>
    </div>
  )
}

export default function UnifiedRepairsDashboard() {
  return (
    <main className="min-h-screen bg-slate-50 p-6 md:p-12 text-slate-800">
      <Suspense fallback={<div className="text-center p-12 text-slate-400">กำลังโหลดระบบซ่อม...</div>}>
        <RepairsContent />
      </Suspense>
    </main>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Swal from 'sweetalert2'

// 📦 1. รวบรวมประเภทอุปกรณ์ทั้งหมดไว้ตรงนี้
const ASSET_TYPES = [
  { value: 'Notebook', label: '💻 (Notebook)' },
  { value: 'Tablet', label: '📱 แท็บเล็ต (Tablet/iPad)' },
  { value: 'Desktop', label: '🖥️ คอมพิวเตอร์ตั้งโต๊ะ (PC)' },
  { value: 'Monitor', label: '📺 จอมอนิเตอร์ (Monitor)' },
  { value: 'Projector', label: '📹 โปรเจกเตอร์ (Projector)' },
  { value: 'Printer', label: '🖨️ เครื่องพิมพ์ (Printer)' },
  { value: 'UPS', label: '🔋 เครื่องสำรองไฟ (UPS)' },
  { value: 'network', label: '🌐 อุปกรณ์เน็ตเวิร์ก (network)' },
  { value: 'Wiring set', label: '🔌 ชุดสายไฟ (Wiring set)' },
  { value: 'Hand tools', label: '🛠️ เครื่องมือช่าง (Hand tools)' },
  { value: 'Signalcable', label: '🔌 สายสัญญาณ (Signalcable)' },
  {value: 'microphone', label: '🎤 ไมโครโฟน (Microphone)' }
]

export default function AssetTable() {
  const [assets, setAssets] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  // ➕ State สำหรับเก็บคำค้นหา
  const [searchTerm, setSearchTerm] = useState('')

  // 🔢 ==========================================
  // ⚙️ ระบบคำนวณและเก็บสถานะ Pagination (หน้าละ 5 รายการ)
  // ==========================================
  const [currentPage, setCurrentPage] = useState(1)
  const itemsPerPage = 5

  // States สำหรับควบคุม Modal
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingAsset, setEditingAsset] = useState<any | null>(null)

  // States สำหรับข้อมูลในฟอร์ม
  const [name, setName] = useState('')
  const [brand, setBrand] = useState('')
  const [assetCode, setAssetCode] = useState('') 
  const [serialNumber, setSerialNumber] = useState('')
  const [contractNumber, setContractNumber] = useState('')
  const [status, setStatus] = useState('Available')
  const [type, setType] = useState('Notebook') 

  // 🔄 ฟังก์ชันดึงข้อมูลทรัพย์สินหลัก
  const fetchAssets = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/assets')
      const json = await res.json()
      if (json.success) {
        setAssets(json.data || json.assets || [])
      }
    } catch (err) {
      console.error('Error fetching assets:', err)
    } finally {
      // 🎯 แก้บั๊กจุดค้าง: บังคับเปลี่ยนสถานะโหลดเป็นเท็จเสมอ ไม่ว่าจะเกิดอะไรขึ้นหน้าจอต้องไม่ค้าง
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchAssets()
  }, [])

  // 🔴 ฟังก์ชันลบครุภัณฑ์
  const handleDelete = async (assetId: number, assetName: string, currentStatus: string) => {
    if (currentStatus === 'Borrowed' || currentStatus === 'borrowed') {
      Swal.fire({
        icon: 'error',
        title: 'ไม่สามารถลบได้!',
        text: `ครุภัณฑ์ "${assetName}" กำลังถูกยืมอยู่ โปรดรับคืนอุปกรณ์ก่อนทำการลบ`,
        confirmButtonColor: '#ef4444'
      })
      return
    }

    const result = await Swal.fire({
      title: 'ยืนยันการลบครุภัณฑ์?',
      text: `คุณกำลังจะลบ "${assetName}" ออกจากระบบอย่างถาวร ยืนยันหรือไม่?`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ef4444',
      cancelButtonColor: '#64748b',
      confirmButtonText: 'ใช่, ลบเลย',
      cancelButtonText: 'ยกเลิก'
    })

    if (!result.isConfirmed) return

    try {
      const res = await fetch(`/api/assets/${assetId}`, {
        method: 'DELETE'
      })
      const json = await res.json()

      if (res.ok && json.success) {
        Swal.fire({ icon: 'success', title: 'ลบข้อมูลสำเร็จ', timer: 1500, showConfirmButton: false })
        fetchAssets()
      } else {
        throw new Error(json.error || 'เกิดข้อผิดพลาดในการลบ')
      }
    } catch (err: any) {
      Swal.fire({ icon: 'error', title: 'ล้มเหลว', text: err.message })
    }
  }

  // ➕ ลอจิกการกรองข้อมูลในตาราง
  const filteredAssets = assets.filter((asset) => {
    const searchLower = searchTerm.toLowerCase().trim()
    if (!searchLower) return true

    return (
      asset.name?.toLowerCase().includes(searchLower) ||
      asset.brand?.toLowerCase().includes(searchLower) ||
      asset.asset_code?.toLowerCase().includes(searchLower) || 
      asset.type?.toLowerCase().includes(searchLower) ||
      asset.serial_number?.toLowerCase().includes(searchLower) ||
      asset.contract_number?.toLowerCase().includes(searchLower)
    )
  })

  // ✂️ คำนวณขอบเขตข้อมูลที่จะตัดมาแสดงเฉพาะหน้านั้นๆ (Slice 5 ชิ้น)
  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const currentAssets = filteredAssets.slice(indexOfFirstItem, indexOfLastItem)

  // 🔢 คำนวณจำนวนหน้าทั้งหมดจากผลลัพธ์ที่ฟิลเตอร์แล้ว
  const totalPages = Math.ceil(filteredAssets.length / itemsPerPage)

  // ✏️ เปิด Modal และดึงค่าเก่ามาหยอดใส่ฟอร์ม
  const openModal = (asset: any | null = null) => {
    if (asset) {
      setEditingAsset(asset)
      setName(asset.name || '')
      setBrand(asset.brand || '')
      setAssetCode(asset.asset_code || '') 
      setSerialNumber(asset.serial_number || '')
      setContractNumber(asset.contract_number || '')
      setType(asset.type || 'Notebook')
      setStatus(asset.status || 'Available')
    } else {
      setEditingAsset(null)
      setName('')
      setBrand('')
      setAssetCode('') 
      setSerialNumber('')
      setContractNumber('')
      setType('Notebook')
      setStatus('Available')
    }
    setIsModalOpen(true)
  }

  // 💾 ฟังก์ชันบันทึกข้อมูล (เพิ่ม/แก้ไข)
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!name.trim()) {
      Swal.fire({ icon: 'warning', title: 'คำเตือน', text: 'กรุณากรอกชื่อครุภัณฑ์' })
      return
    }

    const finalAssetCode = assetCode.trim() === "" ? null : assetCode.trim()
    const finalSerialNumber = serialNumber.trim() === "" ? null : serialNumber.trim()
    const finalContractNumber = contractNumber.trim() === "" ? null : contractNumber.trim()

    const bodyData = editingAsset
      ? { name, brand, type, asset_code: finalAssetCode, serial_number: finalSerialNumber, contract_number: finalContractNumber }
      : { name, brand, type, asset_code: finalAssetCode, serial_number: finalSerialNumber, contract_number: finalContractNumber, status }

    try {
      let res
      if (editingAsset) {
        res = await fetch(`/api/assets/${editingAsset.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(bodyData),
        })
      } else {
        res = await fetch('/api/assets', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(bodyData),
        })
      }

      const json = await res.json()
      if (json.success) {
        setIsModalOpen(false) // 1. สั่งปิดม่าน Modal ทันทีป้องกันแผ่นค้างบังหน้าจอ
        setEditingAsset(null)

        // 2. แจ้งเตือน และสั่ง Re-fetch ข้อมูลเข้าตารางหลังจากหน้าต่างนี้เคลียร์ตัวเองแล้ว
        Swal.fire({
          icon: 'success',
          title: editingAsset ? 'อัปเดตข้อมูลสำเร็จ' : 'เพิ่มอุปกรณ์สำเร็จ',
          timer: 1500,
          showConfirmButton: false
        }).then(() => {
          fetchAssets() // โหลดตารางใหม่แบบลื่นๆ เลยครับช่าง
        })
      } else {
        Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด', text: json.error || 'ไม่สามารถบันทึกข้อมูลได้' })
      }
    } catch (err) {
      console.error(err)
      Swal.fire({ icon: 'error', title: 'ล้มเหลว', text: 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้' })
    }
  }

  if (loading) return <div className="p-12 text-center text-slate-400 animate-pulse">กำลังโหลดข้อมูลครุภัณฑ์...</div>

  return (
    <div className="p-6">
      {/* แถบหัวข้อ + ปุ่มเพิ่มอุปกรณ์ */}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-slate-900">ทะเบียนอุปกรณ์</h3>
          <p className="text-xs text-slate-400">พบอุปกรณ์ทั้งหมด {filteredAssets.length} รายการ</p>
        </div>
        <button
          onClick={() => openModal(null)}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-semibold shadow-sm transition-colors flex items-center justify-center gap-1"
        >
          ➕ เพิ่มอุปกรณ์ใหม่
        </button>
      </div>

      {/* ส่วนกล่องค้นหา */}
      <div className="mb-6">
        <div className="relative max-w-md w-full">
          <span className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-slate-400">
            🔍
          </span>
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value)
              setCurrentPage(1)
            }}
            placeholder="ค้นหาด้วย ชื่อ, แบรนด์, ประเภท, S/N..."
            className="w-full bg-slate-50 border border-slate-200 hover:border-slate-300 focus:border-blue-500 rounded-xl pl-9 pr-4 py-2 text-sm focus:outline-none transition-colors text-slate-800"
          />
          {searchTerm && (
            <button
              onClick={() => {
                setSearchTerm('')
                setCurrentPage(1)
              }}
              className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-400 hover:text-slate-600 text-xs font-bold"
            >
              ล้าง
            </button>
          )}
        </div>
      </div>

      {/* 🧱 ตารางแสดงข้อมูล */}
      <div className="overflow-x-auto border border-slate-200 rounded-xl bg-white shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 text-xs uppercase font-bold tracking-wider">
              <th className="p-4 w-16 text-center font-bold">ลำดับ</th>
              <th className="p-4">ชื่อ / รุ่น</th>
              <th className="p-4">ประเภท</th>
              <th className="p-4">แบรนด์</th>
              <th className="p-4">รหัสทรัพย์สิน</th>
              <th className="p-4">Serial Number</th>
              <th className="p-4">เลขที่สัญญา (Contract)</th>
              <th className="p-4 text-center">สถานะ</th>
              <th className="p-4 text-center">จัดการ</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-sm">
            {currentAssets.length > 0 ? (
              currentAssets.map((asset, index) => (
                <tr key={asset.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="p-4 text-center text-slate-400 font-mono text-xs">{indexOfFirstItem + index + 1}</td>
                  <td className="p-4 font-semibold text-slate-900">{asset.name}</td>

                  <td className="p-4">
                    <span className="px-2.5 py-1 bg-slate-100 text-slate-700 border border-slate-200 rounded-lg text-xs font-medium inline-flex items-center gap-1.5 whitespace-nowrap">
                      <span>{ASSET_TYPES.find(t => t.value === asset.type)?.label.split(' ')[0] || '💻'}</span>
                      <span>{asset.type || 'Notebook'}</span>
                    </span>
                  </td>

                  <td className="p-4 text-slate-600">{asset.brand || '-'}</td>
                  <td className="p-4 text-slate-700 font-mono text-xs font-semibold">{asset.asset_code || '-'}</td>
                  <td className="p-4 text-slate-500 font-mono text-xs">{asset.serial_number || '-'}</td>
                  <td className="p-4 text-slate-500 font-mono text-xs">{asset.contract_number || '-'}</td>
                  <td className="p-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${asset.status === 'Available' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-amber-50 text-amber-700 border-amber-200'
                      }`}>
                      {asset.status || 'Available'}
                    </span>
                  </td>
                  <td className="p-4 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => openModal(asset)}
                        className="text-xs text-blue-600 hover:bg-blue-50 border border-blue-200 px-2.5 py-1 rounded-md transition-colors font-semibold flex items-center gap-1"
                      >
                        ✏️
                      </button>
                      <button
                        onClick={() => handleDelete(asset.id, asset.name, asset.status)}
                        className="text-xs text-red-600 bg-red-50 hover:bg-red-100 border border-red-200 px-2.5 py-1 rounded-md transition-colors font-semibold flex items-center gap-1"
                      >
                        🗑️
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={9} className="p-8 text-center text-slate-400">❌ ไม่พบข้อมูลครุภัณฑ์ที่ตรงกับเงื่อนไขการค้นหา</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 🔢 ส่วนควบคุมปุ่มกดแบ่งหน้า */}
      {totalPages > 1 && (
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mt-4 px-2 gap-3">
          <p className="text-xs text-slate-500 text-center sm:text-left">
            แสดง {indexOfFirstItem + 1} ถึง {Math.min(indexOfLastItem, filteredAssets.length)} จากทั้งหมด {filteredAssets.length} รายการ
          </p>
          
          <div className="flex items-center justify-center space-x-1.5">
            <button
              type="button"
              onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 border border-slate-200 rounded-lg text-xs font-medium bg-white hover:bg-slate-50 text-slate-600 transition-colors disabled:opacity-40 disabled:hover:bg-white"
            >
              ก่อนหน้า
            </button>

            {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
              <button
                key={page}
                type="button"
                onClick={() => setCurrentPage(page)}
                className={`w-7 h-7 flex items-center justify-center border rounded-lg text-xs font-semibold transition-colors ${
                  currentPage === page
                    ? "bg-blue-600 border-blue-600 text-white shadow-sm"
                    : "bg-white border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                {page}
              </button>
            ))}

            <button
              type="button"
              onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-3 py-1.5 border border-slate-200 rounded-lg text-xs font-medium bg-white hover:bg-slate-50 text-slate-600 transition-colors disabled:opacity-40 disabled:hover:bg-white"
            >
              ถัดไป
            </button>
          </div>
        </div>
      )}

      {/* 🌟 หน้าต่างป๊อปอัปฟอร์ม (Modal) นำกลับมาใส่ให้ครบถ้วนแล้วครับช่าง */}
      {isModalOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center z-[9999] p-4 pointer-events-auto"
          onClick={(e) => {
            if (e.target === e.currentTarget) {
              setIsModalOpen(false)
              setEditingAsset(null)
            }
          }}
        >
          <div className="bg-white rounded-2xl w-full max-w-md shadow-xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
              <h4 className="font-bold text-slate-900 text-base">
                {editingAsset ? '📝 แก้ไขข้อมูลครุภัณฑ์' : '➕ เพิ่มครุภัณฑ์ใหม่'}
              </h4>
              <button onClick={() => { setIsModalOpen(false); setEditingAsset(null); }} className="text-slate-400 hover:text-slate-600 text-lg">×</button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">ชื่อ / รุ่น <span className="text-red-500">*</span></label>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="เช่น MacBook Pro 16" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 text-slate-800" required />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">ประเภทอุปกรณ์</label>
                <select
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 text-slate-800"
                >
                  {ASSET_TYPES.map((item) => (
                    <option key={item.value} value={item.value}>
                      {item.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">แบรนด์ / ยี่ห้อ</label>
                <input type="text" value={brand} onChange={(e) => setBrand(e.target.value)} placeholder="เช่น Apple, HP" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 text-slate-800" />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">รหัสทรัพย์สิน (Asset Code)</label>
                <input type="text" value={assetCode} onChange={(e) => setAssetCode(e.target.value)} placeholder="เช่น AC-2026-001" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 font-mono text-slate-800" />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">Serial Number</label>
                <input type="text" value={serialNumber} onChange={(e) => setSerialNumber(e.target.value)} placeholder="เช่น SN-987654321" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 font-mono text-slate-800" />
              </div>

              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">เลขที่สัญญา / ใบจัดซื้อ (Contract Number)</label>
                <input type="text" value={contractNumber} onChange={(e) => setContractNumber(e.target.value)} placeholder="เช่น CN-2026-004" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500 font-mono text-slate-800" />
              </div>

              <div className="flex space-x-3 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => { setIsModalOpen(false); setEditingAsset(null); }} className="w-1/2 bg-slate-100 hover:bg-slate-200 text-slate-600 font-semibold py-2 rounded-xl text-sm transition-colors" >ยกเลิก</button>
                <button type="submit" className="w-1/2 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 rounded-xl text-sm shadow-sm transition-colors" >{editingAsset ? 'อัปเดตข้อมูล' : 'บันทึกข้อมูล'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Swal from 'sweetalert2'
// นำเข้าตัวสร้าง Client จากตัวหลักของแพ็กเกจโดยตรง เพื่อแก้ปัญหาตัวแดง
import { createBrowserClient } from '@supabase/ssr'

// ฟังก์ชันสร้างอินสแตนซ์ Supabase หน้าบ้าน ทำงานร่วมกับระบบคุกกี้เซิร์ฟเวอร์
let supabaseInstance: any = null
function createClient() {
  if (!supabaseInstance) {
    supabaseInstance = createBrowserClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    )
  }
  return supabaseInstance
}

export default function BorrowTable() {
  const supabase = createClient()

  const [borrows, setBorrows] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')
  const [uploadingId, setUploadingId] = useState<number | null>(null) // เช็กสถานะการอัปโหลดแต่ละแถว

  // 🔔 เพิ่ม State สำหรับเก็บรายการที่ต้องตามงาน
  const [urgentItems, setUrgentItems] = useState<any[]>([])

  // 🔢 จัดการระบบแบ่งหน้า (Pagination States)
  const [currentPage, setCurrentPage] = useState(1)
  const itemsPerPage = 5

  
  const fetchBorrows = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/borrows/history')
      const json = await res.json()

      // 🔎 ส่องดูข้อมูลภาพรวมที่ยิงมาจาก API หลังบ้าน
      console.log("📡 ข้อมูลดิบจาก API หลังบ้านที่ส่งมาถึงหน้าบ้าน:", json)

      if (json.success) {
        const data = json.history || json.data || []
        setBorrows(data)

        // 🔎 คำนวณหารายการที่ต้องตามคืน (เลยกำหนดหรือเหลือเวลา 2 วัน)
        const today = new Date()
        const urgent = data.filter((b: any) => {
          if (b.return_date || !b.due_date) return false
          const diffDays = (new Date(b.due_date).getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
          return diffDays <= 2 // เตือนถ้าเหลือเวลา <= 2 วัน หรือเลยกำหนดไปแล้ว
        })
        setUrgentItems(urgent)
      }
    } catch (err) {
      console.error('Error:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchBorrows()
  }, [])

  // 📁 ฟังก์ชันสำหรับแอดมินอัปโหลดเอกสารเซ็นแล้วย้อนหลัง (เข้าตาราง 'documents')
  const handleAdminUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetBorrow: any) => {
    try {
      const file = event.target.files?.[0]
      if (!file) return

      // ดึง ID ออกมาจาก Object ของแถวนั้นตรงๆ ป้องกันการจำสลับแถว
      const borrowId = Number(targetBorrow.id)
      if (!borrowId) {
        Swal.fire("ข้อผิดพลาด", "ไม่พบ ID ของรายการยืม คาดว่าเป็น undefined", "error")
        return
      }

      // 1. ตรวจสอบประเภทไฟล์
      const allowedTypes = ["application/pdf", "image/png", "image/jpeg", "image/jpg"]
      if (!allowedTypes.includes(file.type)) {
        Swal.fire("ข้อผิดพลาด", "รองรับเฉพาะไฟล์ PDF และรูปภาพ (PNG, JPG) เท่านั้นครับ", "error")
        return
      }

      // 2. จำกัดขนาดไฟล์ไม่เกิน 5MB
      if (file.size > 5 * 1024 * 1024) {
        Swal.fire("ข้อผิดพลาด", "ขนาดไฟล์ใหญ่เกินไป ห้ามเกิน 5MB ครับ", "error")
        return
      }

      setUploadingId(borrowId)

      // 3. อัปโหลดไฟล์ขึ้น Supabase Storage (ถัง 'borrow-documents')
      const fileExt = file.name.split(".").pop()
      const fileName = `admin_upload_${borrowId}_${Date.now()}.${fileExt}`
      const filePath = `admin_docs/${fileName}`

      const { error: storageError } = await supabase.storage
        .from("borrow-documents")
        .upload(filePath, file, { cacheControl: "3600", upsert: true })

      if (storageError) throw storageError

      // 4. ดึง Public URL ของไฟล์ออกมา
      const { data: urlData } = supabase.storage
        .from("borrow-documents")
        .getPublicUrl(filePath)

      const publicUrl = urlData.publicUrl

      // 🌟 5. บันทึกข้อมูลแบบ Upsert (เช็กว่ามีเอกสารเดิมของรายการยืมนี้ไหม)
      const { data: existingDoc } = await supabase
        .from("documents")
        .select("id")
        .eq("borrow_id", borrowId)
        .maybeSingle()

      let dbResult;
      if (existingDoc) {
        // ถ้ามีอยู่แล้วให้ Update
        dbResult = await supabase
          .from("documents")
          .update({
            file_url: publicUrl,
            doc_number: `DOC-${borrowId}-${Date.now().toString().slice(-4)}`
          })
          .eq("id", existingDoc.id)
      } else {
        // ถ้ายังไม่มีให้ Insert
        dbResult = await supabase
          .from("documents")
          .insert([
            {
              doc_number: `DOC-${borrowId}-${Date.now().toString().slice(-4)}`,
              doc_type: "ใบขอยืมอุปกรณ์อนุมัติแล้ว",
              file_url: publicUrl,
              borrow_id: borrowId
            }
          ])
      }

      if (dbResult.error) throw dbResult.error

      Swal.fire({
        icon: "success",
        title: existingDoc ? "แก้ไขเอกสารสำเร็จ!" : "อัปโหลดเอกสารสำเร็จ!",
        text: `อัปเดตข้อมูลสำหรับรายการ ID: ${borrowId} เรียบร้อยแล้ว`,
        timer: 1500,
        showConfirmButton: false,
      })

      fetchBorrows() // 🔄 รีโหลดตารางเพื่อให้ปุ่มสลับเป็น "ดูไฟล์" ทันที

    } catch (error: any) {
      console.error("❌ Error Detail:", error);
      Swal.fire("เกิดข้อผิดพลาด", error?.message || "ไม่สามารถอัปโหลดไฟล์ได้", "error")
    } finally {
      setUploadingId(null)
    }
  }

  // 🟢 ฟังก์ชันส่งข้อมูลไปอัปเดตสถานะการคืนของ
  const handleReturn = async (borrowId: number, assetId: number) => {
    const result = await Swal.fire({
      title: 'ยืนยันการคืนครุภัณฑ์?',
      text: "ระบบจะบันทึกวันที่คืนและเปลี่ยนสถานะอุปกรณ์ชิ้นนี้ให้พร้อมใช้งาน",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#10b981',
      cancelButtonColor: '#64748b',
      confirmButtonText: 'ยืนยันการคืน',
      cancelButtonText: 'ยกเลิก'
    })

    if (!result.isConfirmed) return

    try {
      const res = await fetch('/api/borrows/history', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ borrowId, assetId })
      })

      const json = await res.json()

      if (res.ok && json.success) {
        Swal.fire({ icon: 'success', title: 'บันทึกการคืนสำเร็จ', timer: 1500, showConfirmButton: false })
        fetchBorrows()
      } else {
        throw new Error(json.error || 'เกิดข้อผิดพลาด')
      }
    } catch (err: any) {
      Swal.fire({ icon: 'error', title: 'ล้มเหลว', text: err.message })
    }
  }

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value)
    setCurrentPage(1)
  }

  const filteredBorrows = borrows.filter((borrow) => {
    const searchLower = searchTerm.toLowerCase().trim()
    if (!searchLower) return true
    const statusText = borrow.return_date ? 'คืนแล้ว' : 'กำลังยืมอยู่'
    return (
      borrow.borrower_name?.toLowerCase().includes(searchLower) ||
      borrow.borrower_dept?.toLowerCase().includes(searchLower) ||
      (borrow.phone || '').includes(searchLower) ||
      statusText.includes(searchLower) ||
      (borrow.assets?.name?.toLowerCase() || '').includes(searchLower) ||
      (borrow.assets?.serial_number?.toLowerCase() || '').includes(searchLower)
    )
  })

  // 🔢 คำนวณขอบเขตอาเรย์สำหรับการแบ่งหน้า
  const totalPages = Math.ceil(filteredBorrows.length / itemsPerPage)
  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const currentRows = filteredBorrows.slice(indexOfFirstItem, indexOfLastItem)

  const goToPage = (pageNumber: number) => {
    if (pageNumber >= 1 && pageNumber <= totalPages) {
      setCurrentPage(pageNumber)
    }
  }

  if (loading) return <div className="p-12 text-center text-slate-400 animate-pulse">กำลังโหลดประวัติการยืม...</div>

  return (
    <div className="p-4 md:p-6 w-full max-w-full mx-auto">
      
      {/* 🚨 แผงแจ้งเตือนรายการที่ต้องตามงาน */}
      {urgentItems.length > 0 && (
        <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r-xl shadow-sm animate-pulse">
          <h4 className="text-red-700 font-bold text-sm">🔔 ต้องติดตามคืนด่วน ({urgentItems.length} รายการ)</h4>
          <div className="text-xs text-red-600 mt-2 space-y-1">
            {urgentItems.map((item) => (
              <p key={item.id}>• <strong>{item.borrower_name}</strong> ยืม {item.assets?.name} (กำหนด: {new Date(item.due_date).toLocaleDateString('th-TH')})</p>
            ))}
          </div>
        </div>
      )}

      {/* ส่วนหัวแผงควบคุม */}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-slate-900">บันทึกประวัติการยืม-คืนครุภัณฑ์</h3>
          <p className="text-xs text-slate-400">พบประวัติการทำรายการทั้งหมด {filteredBorrows.length} รายการ</p>
        </div>
      </div>

      {/* แถบค้นหา */}
      <div className="mb-6">
        <div className="relative max-w-md w-full">
          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-slate-400">🔍</span>
          <input
            type="text"
            value={searchTerm}
            onChange={handleSearchChange}
            placeholder="ค้นหาด้วย ชื่อ, แผนก, เบอร์โทร หรือพิมพ์ 'กำลังยืม'..."
            className="w-full bg-slate-50 border border-slate-200 hover:border-slate-300 focus:border-blue-500 rounded-xl pl-9 pr-4 py-2 text-sm focus:outline-none text-slate-800"
          />
        </div>
      </div>

      {/* โครงสร้างตารางหลัก */}
      <div className="w-full overflow-x-auto border border-slate-100 rounded-xl bg-white shadow-sm">
        <table className="w-full min-w-[100px] text-left border-collapse table-fixed">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 text-xs uppercase font-bold tracking-wider">
              {[
                { text: "ลำดับ", className: "p-3 w-16 text-center" },
                { text: "ชื่อผู้ยืม", className: "p-3 w-44" },
                { text: "แผนก", className: "p-3 w-32" },
                { text: "อุปกรณ์ที่ยืม", className: "p-3 w-56" },
                { text: "จำนวน", className: "p-3 w-24 text-center" },
                { text: "ประเภท", className: "p-3 w-32" },
                { text: "Serial Number", className: "p-3 w-40" },
                { text: "วันที่ยืม", className: "p-3 w-28" },
                { text: "กำหนดคืน", className: "p-3 w-28" },
                { text: "เบอร์ติดต่อ", className: "p-3 w-32 text-center" },
                { text: "สถานะการคืน", className: "p-3 w-32 text-center" },
                { text: "จัดการ", className: "p-3 w-56 text-center" }
              ].map((header, i) => (
                <th key={i} className={header.className}>{header.text}</th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-xs sm:text-sm">
            {currentRows.length > 0 ? (
              currentRows.map((borrow, index) => {
                const isUrgent = !borrow.return_date && borrow.due_date && 
                  (new Date(borrow.due_date).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24) <= 2;

                return (
                  <tr key={borrow.id} className={`hover:bg-slate-50/50 transition-colors ${isUrgent ? 'bg-red-50' : ''}`}>
                    <td className="p-3 text-center text-slate-400 font-mono text-xs">
                      {indexOfFirstItem + index + 1}
                    </td>
