                  <td className="p-3 text-slate-500 text-xs whitespace-nowrap">{borrow.due_date ? new Date(borrow.due_date).toLocaleDateString('th-TH') : '-'}</td>
                  <td className="p-3 text-center text-slate-700 font-mono text-xs font-medium truncate">{borrow.phone || '-'}</td>
                  <td className="p-3 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold border whitespace-nowrap ${borrow.return_date ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-amber-50 text-amber-700 border-amber-200'
                      }`}>
                      {borrow.return_date ? '● คืนแล้ว' : '● กำลังยืมอยู่'}
                    </span>
                  </td>

                  {/* ปุ่มควบคุมการทำงาน */}
                  <td className="p-3 text-center">
                    <div className="flex items-center justify-center gap-2">

                      {/* ปุ่มคืนของ: แสดงเฉพาะเมื่อยังไม่มี return_date */}
                      {!borrow.return_date && (
                        <button
                          onClick={() => handleReturn(borrow.id, borrow.assets?.id)}
                          className="px-2.5 py-1 bg-blue-50 text-blue-600 hover:bg-blue-100 border border-blue-200 rounded-lg text-xs font-semibold transition-colors"
                        >
                          ↩️ คืนของ
                        </button>
                      )}

                      {/* ปุ่มดูไฟล์ หรือ แนบ/แก้ไขไฟล์ */}
                      <div className="flex flex-col items-center gap-1">
                        {borrow.file_url && (
                          <a
                            href={borrow.file_url}
                            target="_blank"
                            rel="noreferrer"
                            className="px-2 py-1 bg-emerald-50 text-emerald-600 hover:bg-emerald-100 border border-emerald-200 rounded-lg text-[10px] font-bold transition-colors w-full text-center"
                          >
                            👁️ ดูไฟล์
                          </a>
                        )}
                        <label className={`cursor-pointer px-2 py-1 rounded-lg text-[10px] font-bold border transition-all w-full text-center
                          ${borrow.file_url 
                            ? 'bg-slate-50 text-slate-400 border-slate-100 opacity-60 hover:opacity-100' 
                            : 'bg-blue-50 text-blue-600 border-blue-200 hover:bg-blue-100'
                          } ${uploadingId === borrow.id ? 'cursor-wait opacity-50' : ''}`}
                        >
                          {uploadingId === borrow.id ? '⌛...' : (borrow.file_url ? '🔄 แก้ไข' : '📁 แนบไฟล์')}
                          <input
                            type="file"
                            className="hidden"
                            disabled={uploadingId !== null}
                            onChange={(e) => handleAdminUpload(e, borrow)}
                          />
                        </label>
                      </div>

                    </div>
                  </td>
                </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={12} className="p-8 text-center text-slate-400">❌ ไม่พบประวัติการยืมที่ตรงกับเงื่อนไข</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* ระบบแบ่งหน้า (Pagination Controls) */}
      {totalPages > 1 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-4 py-3 px-4 bg-white border border-slate-100 rounded-xl text-xs sm:text-sm shadow-sm">
          <div className="text-slate-500 text-center sm:text-left">
            แสดงรายการที่ <span className="font-semibold text-slate-700">{indexOfFirstItem + 1}</span> ถึง{" "}
            <span className="font-semibold text-slate-700">
              {Math.min(indexOfLastItem, filteredBorrows.length)}
            </span>{" "}
            จากทั้งหมด <span className="font-semibold text-slate-700">{filteredBorrows.length}</span> รายการ
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => goToPage(currentPage - 1)}
              disabled={currentPage === 1}
              className="px-3 py-2 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-600 disabled:opacity-40 disabled:hover:bg-white font-medium transition-all select-none"
            >
              ◀ ก่อนหน้า
            </button>
            <span className="text-slate-700 font-semibold bg-slate-100 px-3 py-1.5 rounded-lg">
              หน้า {currentPage} / {totalPages}
            </span>
            <button
              onClick={() => goToPage(currentPage + 1)}
              disabled={currentPage === totalPages}
              className="px-3 py-2 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-600 disabled:opacity-40 disabled:hover:bg-white font-medium transition-all select-none"
            >
              ถัดไป ▶
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

// components/DocumentUploader.tsx
"use client";

import { useState } from "react";
import { createClient } from "@supabase/supabase-js";
import Swal from "sweetalert2";

// เรียกใช้งาน Supabase Client ของคุณ
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

interface UploaderProps {
  borrowId: number;             // ID ของรายการยืมจากแถวในตาราง
  onUploadSuccess?: () => void;  // ฟังก์ชันสั่งโหลดข้อมูลในหน้าตารางใหม่หลังอัปโหลดเสร็จ
}

export default function DocumentUploader({ borrowId, onUploadSuccess }: UploaderProps) {
  const [uploading, setUploading] = useState(false);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    try {
      const file = event.target.files?.[0];
      if (!file) return;

      // 1. ตรวจสอบประเภทไฟล์ (PDF, PNG, JPG)
      const allowedTypes = ["application/pdf", "image/png", "image/jpeg", "image/jpg"];
      if (!allowedTypes.includes(file.type)) {
        Swal.fire("ข้อผิดพลาด", "รองรับเฉพาะไฟล์ PDF และรูปภาพ (PNG, JPG) เท่านั้นครับ", "error");
        return;
      }

      // 2. จำกัดขนาดไฟล์ไม่เกิน 5MB
      if (file.size > 5 * 1024 * 1024) {
        Swal.fire("ข้อผิดพลาด", "ขนาดไฟล์ใหญ่เกินไป ห้ามเกิน 5MB ครับ", "error");
        return;
      }

      setUploading(true);

      // 3. ตั้งชื่อไฟล์เพื่อนำไปเก็บใน Storage (แบ่งโฟลเดอร์สำหรับแอดมินอัปโหลดแยกไว้)
      const fileExt = file.name.split(".").pop();
      const fileName = `admin_upload_${borrowId}_${Date.now()}.${fileExt}`;
      const filePath = `admin_docs/${fileName}`;

      // 4. สั่งอัปโหลดไฟล์ไปยัง Supabase Storage Bucket ('borrow-documents')
      const { data: storageData, error: storageError } = await supabase.storage
        .from("borrow-documents")
        .upload(filePath, file, {
          cacheControl: "3600",
          upsert: true,
        });

      if (storageError) throw storageError;

      // 5. ดึง Public URL เพื่อเอามาเก็บในดาต้าเบส
      const { data: urlData } = supabase.storage
        .from("borrow-documents")
        .getPublicUrl(filePath);

      const publicUrl = urlData.publicUrl;

      // 🌟 6. บันทึกข้อมูลแยกเข้าตาราง 'documents' โดยเอาไปผูกกับ borrowId ของแถวนั้น
      const { error: dbError } = await supabase
        .from("documents")
        .insert([
          {
            doc_number: `DOC-${borrowId}-${Date.now().toString().slice(-4)}`, // เจนรหัสเอกสารอ้างอิง ID รายการยืม
            doc_type: "ใบขอยืมอุปกรณ์อนุมัติแล้ว", // ระบุประเภทเอกสารย้อนหลัง
            file_url: publicUrl,                 // เก็บลิงก์ไฟล์ไว้ที่นี่
            borrow_id: borrowId                  // 🔗 ผูกความสัมพันธ์กับไอดีรายการยืมย้อนหลัง
          }
        ]);

      if (dbError) throw dbError;

      Swal.fire({
        icon: "success",
        title: "อัปโหลดเอกสารย้อนหลังสำเร็จ!",
        text: "ไฟล์เอกสารได้รับการบันทึกเข้าตารางเรียบร้อยแล้ว",
        timer: 2000,
        showConfirmButton: false,
      });

      // สั่งให้หน้าหลักดึงข้อมูลใหม่ เพื่ออัปเดตสถานะปุ่ม
      if (onUploadSuccess) onUploadSuccess();
      
    } catch (error: any) {
      console.error("Upload Error:", error);
      Swal.fire("เกิดข้อผิดพลาด", error.message || "ไม่สามารถอัปโหลดไฟล์ได้", "error");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="flex items-center">
      <label className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium cursor-pointer transition-all border
        ${uploading 
          ? "bg-slate-700 text-slate-400 border-slate-600 cursor-not-allowed" 
          : "bg-slate-800 text-slate-200 border-slate-700 hover:bg-slate-700 hover:text-white"
        }`}
      >
        <span>{uploading ? "กำลังอัปโหลด..." : "📁 อัปโหลดเอกสารย้อนหลัง"}</span>
        <input
          type="file"
          accept=".pdf, .png, .jpg, .jpeg"
          className="hidden"
          onChange={handleFileUpload}
          disabled={uploading}
        />
      </label>
    </div>
  );
}

"use client";

import { useState } from "react";
import { createBrowserClient } from "@supabase/ssr";
import Swal from "sweetalert2";

// ฟังก์ชันสร้างอินสแตนซ์ Supabase หน้าบ้าน
let supabaseInstance: any = null
function createClient() {
  if (!supabaseInstance) {
    supabaseInstance = createBrowserClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    )
  }
  return supabaseInstance
}

interface RepairUploaderProps {
  repairId: number;
  onUploadSuccess?: () => void;
}

export default function RepairDocumentUploader({ repairId, onUploadSuccess }: RepairUploaderProps) {
  const [uploading, setUploading] = useState(false);
  const supabase = createClient();

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    try {
      const file = event.target.files?.[0];
      if (!file) return;

      // 1. ตรวจสอบประเภทไฟล์
      const allowedTypes = ["application/pdf", "image/png", "image/jpeg", "image/jpg"];
      if (!allowedTypes.includes(file.type)) {
        Swal.fire("ข้อผิดพลาด", "รองรับเฉพาะไฟล์ PDF และรูปภาพ (PNG, JPG) เท่านั้นครับ", "error");
        return;
      }

      // 2. จำกัดขนาดไฟล์ไม่เกิน 5MB
      if (file.size > 5 * 1024 * 1024) {
        Swal.fire("ข้อผิดพลาด", "ขนาดไฟล์ใหญ่เกินไป ห้ามเกิน 5MB ครับ", "error");
        return;
      }

      setUploading(true);

      // 3. ตั้งชื่อไฟล์และอัปโหลดไปยัง storage
      const fileExt = file.name.split(".").pop();
      const fileName = `repair_upload_${repairId}_${Date.now()}.${fileExt}`;
      const filePath = `repair_docs/${fileName}`;

      const { data: storageData, error: storageError } = await supabase.storage
        .from("repair-documents") // ต้องสร้าง Bucket นี้ใน Supabase Storage
        .upload(filePath, file, {
          cacheControl: "3600",
          upsert: true,
        });

      if (storageError) {
        // ถ้าไม่มี Bucket อาจจะเกิด Error นี้ แนะนำให้สร้าง Bucket ชื่อ 'repair-documents'
        throw storageError;
      }

      // 4. ดึง Public URL
      const { data: urlData } = supabase.storage
        .from("repair-documents")
        .getPublicUrl(filePath);

      const publicUrl = urlData.publicUrl;

      // 5. บันทึกข้อมูลเข้าตาราง 'documents' แบบ Upsert
      // โดยใช้ repair_id เป็นเกณฑ์ในการเช็กว่ามีเอกสารเดิมอยู่แล้วหรือไม่
      
      // ดึงเอกสารเดิมถ้ามี
      const { data: existingDoc } = await supabase
        .from("documents")
        .select("id")
        .eq("repair_id", repairId)
        .maybeSingle();

      let dbResult;
      if (existingDoc) {
        // ถ้ามีอยู่แล้วให้ Update
        dbResult = await supabase
          .from("documents")
          .update({
            file_url: publicUrl,
            doc_number: `RE-DOC-${repairId}-${Date.now().toString().slice(-4)}`
          })
          .eq("id", existingDoc.id);
      } else {
        // ถ้ายังไม่มีให้ Insert
        dbResult = await supabase
          .from("documents")
          .insert([
            {
              doc_number: `RE-DOC-${repairId}-${Date.now().toString().slice(-4)}`,
              doc_type: "เอกสารประกอบการซ่อม",
              file_url: publicUrl,
              repair_id: repairId
            }
          ]);
      }

      if (dbResult.error) throw dbResult.error;

      Swal.fire({
        icon: "success",
        title: "อัปโหลดเอกสารสำเร็จ!",
        text: "ไฟล์เอกสารได้รับการบันทึกเรียบร้อยแล้ว",
        timer: 1500,
        showConfirmButton: false,
      });

      if (onUploadSuccess) onUploadSuccess();
      
    } catch (error: any) {
      console.error("Upload Error:", error);
      Swal.fire("เกิดข้อผิดพลาด", error.message || "ไม่สามารถอัปโหลดไฟล์ได้ (ตรวจสอบว่ามี Bucket 'repair-documents' และคอลัมน์ 'repair_id' ในตาราง 'documents' หรือไม่)", "error");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="flex items-center">
      <label className={`flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold cursor-pointer transition-all border
        ${uploading 
          ? "bg-slate-100 text-slate-400 border-slate-200 cursor-not-allowed" 
          : "bg-white text-blue-600 border-blue-200 hover:bg-blue-50"
        }`}
      >
        <span>{uploading ? "⌛..." : "📁 แนบไฟล์"}</span>
        <input
          type="file"
          accept=".pdf, .png, .jpg, .jpeg"
          className="hidden"
          onChange={handleFileUpload}
          disabled={uploading}
        />
      </label>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import Swal from 'sweetalert2'

const REPAIR_STATUS = [
  { value: 'Pending', label: '⏳ รอดำเนินการ', color: 'bg-amber-50 text-amber-700 border-amber-200' },
  { value: 'In Progress', label: '🛠️ กำลังซ่อม', color: 'bg-blue-50 text-blue-700 border-blue-200' },
  { value: 'Completed', label: '✅ เสร็จสิ้น', color: 'bg-emerald-50 text-emerald-700 border-emerald-200' }
]

export default function RepairManageTable() {
  const [repairs, setRepairs] = useState<any[]>([])
  const [parts, setParts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')

  // Modal states
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingRepair, setEditingRepair] = useState<any | null>(null)

  // Form states for Technician
  const [status, setStatus] = useState('Pending')
  const [technicianName, setTechnicianName] = useState('')
  const [fixDetail, setFixDetail] = useState('')
  const [servicePrice, setServicePrice] = useState<number>(0)
  
  // Spare Parts Usage State: [{ part_id, quantity }]
  const [partsUsage, setPartsUsage] = useState<any[]>([])

  const fetchRepairs = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/repairs')
      const json = await res.json()
      if (json.success) setRepairs(json.data || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const fetchParts = async () => {
    try {
      const res = await fetch('/api/spare-parts')
      const json = await res.json()
      if (json.success) setParts(json.data || [])
    } catch (err) {
      console.error(err)
    }
  }

  useEffect(() => {
    fetchRepairs()
    fetchParts()
  }, [])

  const openManageModal = (repair: any) => {
    setEditingRepair(repair)
    setStatus(repair.status || 'Pending')
    setTechnicianName(repair.technician_name || '')
    setFixDetail(repair.fix_detail || '')
    setServicePrice(repair.service_price || 0)
    setPartsUsage([]) // รีเซ็ตรายการอะไหล่ทุกครั้งที่เปิดใหม่
    setIsModalOpen(true)
  }

  const addPartRow = () => {
    setPartsUsage([...partsUsage, { part_id: '', quantity: 1 }])
  }

  const removePartRow = (index: number) => {
    const newList = [...partsUsage]
    newList.splice(index, 1)
    setPartsUsage(newList)
  }

  const updatePartUsage = (index: number, field: string, value: any) => {
    const newList = [...partsUsage]
    newList[index][field] = value
    setPartsUsage(newList)
  }

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault()
    
    // กรองเอาเฉพาะแถวที่เลือกอะไหล่จริงๆ
    const validPartsUsage = partsUsage.filter(p => p.part_id !== '')

    // 🚩 Validation: ถ้ามีการเบิกอะไหล่ ต้องเปลี่ยนสถานะเป็น 'Completed' เท่านั้น
    if (validPartsUsage.length > 0 && status !== 'Completed') {
      Swal.fire({
        icon: 'warning',
        title: 'ไม่สามารถบันทึกได้',
        text: 'หากมีการเบิกใช้อะไหล่ กรุณาเปลี่ยนสถานะงานเป็น "เสร็จสิ้น" เพื่อตัดสต็อกและปิดงานครับ',
        confirmButtonColor: '#3b82f6'
      })
      return
    }

    const bodyData = {
      status,
      technician_name: technicianName,
      fix_detail: fixDetail,
      service_price: servicePrice,
      parts_usage: validPartsUsage,
      repair_item_id: editingRepair?.item?.id || null
    }

    try {
      const res = await fetch(`/api/repairs/${editingRepair.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyData),
      })

      const json = await res.json()
      if (json.success) {
        setIsModalOpen(false)
        Swal.fire({ icon: 'success', title: 'อัปเดตงานซ่อมเรียบร้อย', timer: 1500, showConfirmButton: false })
        fetchRepairs()
        fetchParts() // โหลดสต็อกใหม่หลังตัดสต็อก
      }
    } catch (err) {
      Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด' })
    }
  }

  const filteredRepairs = repairs.filter((r) => {
    if (r.status === 'Completed') return false
    const searchLower = searchTerm.toLowerCase().trim()
    return (
      r.requester_name?.toLowerCase().includes(searchLower) ||
      r.item?.manual_brand?.toLowerCase().includes(searchLower) ||
      r.item?.assets_number?.toLowerCase().includes(searchLower)
    )
  })

  if (loading) return <div className="p-12 text-center text-slate-400">กำลังโหลดรายการงานซ่อม...</div>

  return (
    <div className="p-6">
      <div className="mb-6 flex justify-between items-center">
        <h3 className="font-bold text-slate-800">งานซ่อมที่กำลังดำเนินการ</h3>
        <div className="relative max-w-xs w-full">
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="ค้นหาชื่อผู้แจ้ง, เลขครุภัณฑ์..."
            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:outline-none focus:border-blue-500"
          />
        </div>
      </div>

      <div className="overflow-x-auto border border-slate-100 rounded-2xl">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-slate-500 text-xs uppercase font-bold border-b">
              <th className="p-4">วันที่แจ้ง</th>
              <th className="p-4">ผู้แจ้ง / แผนก</th>
              <th className="p-4">อุปกรณ์ / อาการเสีย</th>
              <th className="p-4 text-center">สถานะ</th>
              <th className="p-4 text-center">จัดการ</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredRepairs.map((repair) => (
              <tr key={repair.id} className="hover:bg-slate-50/50 transition-colors text-sm">
                <td className="p-4 text-xs text-slate-500">
                  {new Date(repair.repair_date).toLocaleDateString('th-TH')}
                </td>
                <td className="p-4">
                  <div className="font-bold text-slate-900">{repair.requester_name}</div>
                  <div className="text-[10px] text-slate-500 uppercase">{repair.requester_dept}</div>
                </td>
                <td className="p-4">
                  <div className="font-semibold text-blue-600">{repair.item?.manual_brand}</div>
                  <div className="text-[10px] text-slate-400 font-mono italic">{repair.item?.problem_detail}</div>
                </td>
                <td className="p-4 text-center">
                  <span className={`px-3 py-1 rounded-full text-[10px] font-bold border ${REPAIR_STATUS.find(s => s.value === repair.status)?.color}`}>
                    {REPAIR_STATUS.find(s => s.value === repair.status)?.label.split(' ')[1] || repair.status}
                  </span>
                </td>
                <td className="p-4 text-center">
                  <button
                    onClick={() => openManageModal(repair)}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all shadow-sm"
                  >
                    🛠️ ดำเนินการ
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
              <h4 className="font-bold flex items-center gap-2"><span>🛠️</span> บันทึกการดำเนินการซ่อม</h4>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white text-2xl">×</button>
            </div>
            
            <form onSubmit={handleUpdate} className="p-6 space-y-6 overflow-y-auto">
              {/* ข้อมูลเบื้องต้น */}
              <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl text-xs space-y-1">
                 <p className="font-bold text-blue-800 mb-2">📌 รายละเอียดเบื้องต้น:</p>
                 <p className="text-blue-700"><b>อุปกรณ์:</b> {editingRepair?.item?.manual_brand} </p>
                 <p className="text-blue-700"><b>อาการ:</b> {editingRepair?.item?.problem_detail}</p>
              </div>

              {/* ส่วนจัดการสถานะ */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold uppercase text-slate-500 mb-1.5">สถานะงาน</label>
                  <select value={status} onChange={(e) => setStatus(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:border-blue-500 outline-none">
                    {REPAIR_STATUS.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold uppercase text-slate-500 mb-1.5">ช่างผู้รับผิดชอบ</label>
                  <input type="text" value={technicianName} onChange={(e) => setTechnicianName(e.target.value)} placeholder="ระบุชื่อช่าง" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:border-blue-500 outline-none" required />
                </div>
              </div>

              {/* ส่วนของอะไหล่ */}
              <div className="border-t border-slate-100 pt-5">
                <div className="flex justify-between items-center mb-3">
                  <label className="text-xs font-bold uppercase text-emerald-600 flex items-center gap-1">
                    <span>📦</span> การเบิกใช้อะไหล่
                  </label>
                  <button type="button" onClick={addPartRow} className="text-[10px] bg-emerald-50 text-emerald-600 border border-emerald-200 px-2 py-1 rounded-lg font-bold hover:bg-emerald-100 transition-colors">
                    + เพิ่มอะไหล่
                  </button>
                </div>
                
                {partsUsage.length > 0 ? (
                  <div className="space-y-3">
                    {partsUsage.map((usage, idx) => (
                      <div key={idx} className="flex gap-2 items-center animate-in fade-in slide-in-from-left-2 duration-300">
                        <select
                          value={usage.part_id}
                          onChange={(e) => updatePartUsage(idx, 'part_id', e.target.value)}
                          className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs focus:border-emerald-500 outline-none"
                        >
                          <option value="">-- เลือกอะไหล่ --</option>
                          {parts.map(p => (
                            <option key={p.id} value={p.id} disabled={p.stock_quantity <= 0}>
                              {p.part_name} (คงเหลือ: {p.stock_quantity})
                            </option>
                          ))}
                        </select>
                        <input
                          type="number"
                          min="1"
                          value={usage.quantity}
                          onChange={(e) => updatePartUsage(idx, 'quantity', parseInt(e.target.value))}
                          className="w-16 bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-xs text-center focus:border-emerald-500 outline-none"
                        />
                        <button type="button" onClick={() => removePartRow(idx)} className="text-red-400 hover:text-red-600 p-1">✕</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-[10px] text-slate-400 italic text-center py-2 bg-slate-50 rounded-xl border border-dashed border-slate-200">ยังไม่มีการเบิกอะไหล่</p>
                )}
              </div>

              {/* รายละเอียดการแก้ไข */}
              <div className="border-t border-slate-100 pt-5">
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div>
                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1.5">รายละเอียดการแก้ไข</label>
                    <textarea
                      value={fixDetail}
                      onChange={(e) => setFixDetail(e.target.value)}
                      placeholder="ช่างทำการแก้ไขอย่างไรบ้าง..."
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-blue-500 outline-none"
                      rows={3}
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1.5">ค่าบริการ / ค่าดำเนินการ (บาท)</label>
                    <input 
                      type="number" 
                      value={servicePrice} 
                      onChange={(e) => setServicePrice(parseFloat(e.target.value) || 0)} 
                      placeholder="0.00" 
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:border-blue-500 outline-none" 
                    />
                    <p className="text-[10px] text-slate-400 mt-2 italic">* ไม่รวมค่าอะไหล่ที่เบิกใช้</p>
                  </div>
                </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-slate-100 sticky bottom-0 bg-white shrink-0">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold py-3 rounded-2xl transition-colors">ยกเลิก</button>
                <button type="submit" className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-2xl shadow-lg shadow-blue-200 transition-all active:scale-95">บันทึกปิดงาน</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import Swal from 'sweetalert2'
import * as XLSX from 'xlsx'
import { generateRepairPDF } from '@/app/repairs/manage/generateRepairPDF'
import RepairDocumentUploader from './RepairDocumentUploader'

const REPAIR_STATUS = [
  { value: 'Pending', label: '⏳ รอดำเนินการ (Pending)', color: 'bg-amber-50 text-amber-700 border-amber-200' },
  { value: 'In Progress', label: '🛠️ กำลังซ่อม (In Progress)', color: 'bg-blue-50 text-blue-700 border-blue-200' },
  { value: 'Completed', label: '✅ เสร็จสิ้น (Completed)', color: 'bg-emerald-50 text-emerald-700 border-emerald-200' }
]

export default function RepairTable() {
  const [repairs, setRepairs] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')

  // Filter states (Monthly Summary)
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1)
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear())

  // Pagination states
  const [currentPage, setCurrentPage] = useState(1)
  const itemsPerPage = 5

  // Modal states (Editing Only)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingRepair, setEditingRepair] = useState<any | null>(null)

  // Form states (For Editing)
  const [requesterName, setRequesterName] = useState('')
  const [requesterDept, setRequesterDept] = useState('')
  const [requesterPhone, setRequesterPhone] = useState('')
  const [requesterPosition, setRequesterPosition] = useState('')
  const [requesterEmpCode, setRequesterEmpCode] = useState('')
  const [problemDetail, setProblemDetail] = useState('')
  const [assetsNumber, setAssetsNumber] = useState('')
  const [manualContract, setManualContract] = useState('')
  const [typeItem, setTypeItem] = useState('')
  const [status, setStatus] = useState('Pending')

  const fetchRepairs = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/repairs')
      const json = await res.json()
      if (json.success) {
        setRepairs(json.data || [])
      }
    } catch (err) {
      console.error('Error fetching repairs:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchRepairs()
  }, [])

  const openModal = (repair: any) => {
    setEditingRepair(repair)
    setRequesterName(repair.requester_name || '')
    setRequesterDept(repair.requester_dept || '')
    setRequesterPhone(repair.requester_phone || '')
    setRequesterPosition(repair.requester_position || '')
    setRequesterEmpCode(repair.requester_emp_code || '')
    setProblemDetail(repair.item?.problem_detail || '')
    setAssetsNumber(repair.item?.assets_number || '')
    setManualContract(repair.item?.manual_contract || '')
    setTypeItem(repair.item?.type_item || '')
    setStatus(repair.status || 'Pending')
    setIsModalOpen(true)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    const bodyData = {
      requester_name: requesterName,
      requester_dept: requesterDept,
      requester_phone: requesterPhone,
      requester_position: requesterPosition,
      requester_emp_code: requesterEmpCode,
      problem_detail: problemDetail,
      assets_number: assetsNumber,
      manual_contract: manualContract,
      type_item: typeItem,
      status,
      repair_item_id: editingRepair?.item?.id || null
    }

    try {
      const res = await fetch(`/api/repairs/${editingRepair.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyData),
      })

      const json = await res.json()
      if (json.success) {
        setIsModalOpen(false)
        Swal.fire({
          icon: 'success',
          title: 'อัปเดตข้อมูลสำเร็จ',
          timer: 1500,
          showConfirmButton: false
        })
        fetchRepairs()
      } else {
        Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด', text: json.error || 'ไม่สามารถบันทึกข้อมูลได้' })
      }
    } catch (err) {
      console.error(err)
      Swal.fire({ icon: 'error', title: 'ล้มเหลว', text: 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้' })
    }
  }

  const handleDelete = async (id: number) => {
    const result = await Swal.fire({
      title: 'ยืนยันการลบ?',
      text: "คุณต้องการลบข้อมูลการแจ้งซ่อมนี้ใช่หรือไม่?",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ef4444',
      cancelButtonColor: '#64748b',
      confirmButtonText: 'ใช่, ลบเลย',
      cancelButtonText: 'ยกเลิก'
    })

    if (!result.isConfirmed) return

    try {
      const res = await fetch(`/api/repairs/${id}`, { method: 'DELETE' })
      const json = await res.json()
      if (json.success) {
        Swal.fire({ icon: 'success', title: 'ลบสำเร็จ', timer: 1500, showConfirmButton: false })
        fetchRepairs()
      }
    } catch (err) {
      Swal.fire({ icon: 'error', title: 'ล้มเหลว', text: 'ลบข้อมูลไม่สำเร็จ' })
    }
  }

  const filteredRepairs = repairs.filter((r) => {
    const searchLower = searchTerm.toLowerCase().trim()
    if (!searchLower) return true
    return (
      r.requester_name?.toLowerCase().includes(searchLower) ||
      r.requester_emp_code?.toLowerCase().includes(searchLower) ||
      r.requester_dept?.toLowerCase().includes(searchLower) ||
      r.item?.manual_brand?.toLowerCase().includes(searchLower) ||
      r.item?.problem_detail?.toLowerCase().includes(searchLower) ||
      r.item?.manual_sn?.toLowerCase().includes(searchLower) ||
      r.item?.assets_number?.toLowerCase().includes(searchLower) ||
      r.item?.manual_contract?.toLowerCase().includes(searchLower) ||
      r.item?.type_item?.toLowerCase().includes(searchLower)
    )
  })

  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const currentRepairs = filteredRepairs.slice(indexOfFirstItem, indexOfLastItem)
  const totalPages = Math.ceil(filteredRepairs.length / itemsPerPage)

  if (loading) return <div className="p-12 text-center text-slate-400 animate-pulse">กำลังโหลดข้อมูลการซ่อม...</div>

  // คำนวณสรุปยอดรายเดือน (เฉพาะข้อมูลที่กรองตามเดือน/ปี)
  const monthlyData = repairs.filter(r => {
    const date = new Date(r.repair_date)
    return (date.getMonth() + 1) === selectedMonth && date.getFullYear() === selectedYear
  })

  const summary = {
    count: monthlyData.length,
    parts: monthlyData.reduce((sum, r) => sum + (Number(r.total_parts_cost) || 0), 0),
    partsQty: monthlyData.reduce((sum, r) => sum + (Number(r.total_parts_qty) || 0), 0),
    service: monthlyData.reduce((sum, r) => sum + (Number(r.service_price) || 0), 0),
    total: monthlyData.reduce((sum, r) => sum + (Number(r.grand_total) || 0), 0),
    // 📊 เพิ่มการจำแนกตามประเภทอุปกรณ์
    countsByType: monthlyData.reduce((acc: any, r) => {
      const type = r.item?.type_item || 'ไม่ระบุประเภท'
      acc[type] = (acc[type] || 0) + 1
      return acc
    }, {})
  }

  const exportToExcel = () => {
    try {
      // 1. เตรียมข้อมูลสำหรับ Sheet รายละเอียด
      const detailedData = monthlyData.map((r, index) => ({
        'ลำดับ': index + 1,
        'วันที่แจ้งซ่อม': new Date(r.repair_date).toLocaleDateString('th-TH'),
        'วันที่เสร็จสิ้น': r.repair_finish ? new Date(r.repair_finish).toLocaleDateString('th-TH') : '-',
        'ชื่อผู้แจ้ง': r.requester_name,
        'แผนก': r.requester_dept,
        'อุปกรณ์': r.item?.manual_brand || '-',
        'เลขครุภัณฑ์': r.item?.assets_number || '-',
        'อาการเสีย': r.item?.problem_detail || '-',
        'สถานะ': REPAIR_STATUS.find(s => s.value === r.status)?.label.split(' ')[1] || r.status,
        'ค่าอะไหล่ (บาท)': r.total_parts_cost || 0,
        'ค่าบริการ (บาท)': r.service_price || 0,
        'ยอดรวมสุทธิ (บาท)': r.grand_total || 0,
        'ช่างผู้ซ่อม': r.technician_name || '-'
      }))

      // 2. เตรียมข้อมูลสำหรับ Sheet สรุปยอด
      const summaryData = [
        { 'หัวข้อ': 'เดือน/ปี', 'ข้อมูล': `${new Date(0, selectedMonth - 1).toLocaleString('th-TH', { month: 'long' })} ${selectedYear + 543}` },
        { 'หัวข้อ': 'จำนวนงานซ่อมทั้งหมด', 'ข้อมูล': `${summary.count} รายการ` },
        { 'หัวข้อ': 'รวมค่าอะไหล่', 'ข้อมูล': summary.parts.toLocaleString(undefined, { minimumFractionDigits: 2 }) },
        { 'หัวข้อ': 'จำนวนอะไหล่ที่ใช้รวม', 'ข้อมูล': `${summary.partsQty} ชิ้น` },
        { 'หัวข้อ': 'รวมค่าบริการ', 'ข้อมูล': summary.service.toLocaleString(undefined, { minimumFractionDigits: 2 }) },
        { 'หัวข้อ': 'งบประมาณรวมทั้งสิ้น', 'ข้อมูล': summary.total.toLocaleString(undefined, { minimumFractionDigits: 2 }) }
      ]

      // 3. สร้าง Workbook และเพิ่ม Sheets
      const wb = XLSX.utils.book_new()
      const wsDetails = XLSX.utils.json_to_sheet(detailedData)
      const wsSummary = XLSX.utils.json_to_sheet(summaryData)

      XLSX.utils.book_append_sheet(wb, wsSummary, "สรุปยอดรายเดือน")
      XLSX.utils.book_append_sheet(wb, wsDetails, "รายละเอียดงานซ่อม")

      // 4. บันทึกไฟล์
      const fileName = `รายงานการซ่อม_${selectedMonth}_${selectedYear + 543}.xlsx`
      XLSX.writeFile(wb, fileName)

      Swal.fire({ icon: 'success', title: 'ส่งออกไฟล์สำเร็จ', text: fileName, timer: 2000, showConfirmButton: false })
    } catch (err) {
      console.error(err)
      Swal.fire({ icon: 'error', title: 'ส่งออกล้มเหลว', text: 'เกิดข้อผิดพลาดในการสร้างไฟล์ Excel' })
    }
  }

  return (
    <div className="p-6">
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-slate-900">Repair Management System</h3>
          <p className="text-xs text-slate-400">พบรายการแจ้งซ่อมทั้งหมด {filteredRepairs.length} รายการ</p>
        </div>
      </div>

      {/* 📊 Monthly Dashboard Section */}
      <div className="bg-white border border-slate-200 rounded-2xl p-6 mb-8 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 rounded-lg text-white">📈</div>
            <div>
              <h4 className="font-bold text-slate-800">สรุปยอดการซ่อมรายเดือน</h4>
              <p className="text-[10px] text-slate-400 uppercase tracking-wider">Financial & Repair Analytics</p>
            </div>
          </div>
          
          <div className="flex flex-wrap items-center gap-2">
            <button 
              onClick={exportToExcel}
              className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-md shadow-emerald-100 flex items-center gap-2"
            >
              <span>📊</span> Export to Excel
            </button>
            <div className="h-8 w-px bg-slate-200 mx-2 hidden md:block"></div>
            <select 
              value={selectedMonth} 
              onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
              className="bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-blue-500"
            >
              {Array.from({ length: 12 }, (_, i) => (
                <option key={i + 1} value={i + 1}>
                  {new Date(0, i).toLocaleString('th-TH', { month: 'long' })}
                </option>
              ))}
            </select>
            <select 
              value={selectedYear} 
              onChange={(e) => setSelectedYear(parseInt(e.target.value))}
              className="bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 outline-none focus:border-blue-500"
            >
              {[2024, 2025, 2026, 2027].map(y => (
                <option key={y} value={y}>{y + 543}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl">
            <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">จำนวนงานซ่อม</p>
            <p className="text-2xl font-black text-slate-800">{summary.count} <span className="text-sm font-medium text-slate-400">รายการ</span></p>
          </div>
          <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl">
            <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">ค่าอะไหล่รวม</p>
            <p className="text-2xl font-black text-emerald-600">฿{summary.parts.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
          </div>
          <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl">
            <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">จำนวนอะไหล่รวม</p>
            <p className="text-2xl font-black text-amber-600">{summary.partsQty} <span className="text-sm font-medium text-slate-400">ชิ้น</span></p>
          </div>
          <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl">
            <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">ค่าบริการรวม</p>
            <p className="text-2xl font-black text-blue-600">฿{summary.service.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
          </div>
          <div className="bg-blue-600 p-4 rounded-2xl shadow-lg shadow-blue-100 col-span-1 sm:col-span-2 lg:col-span-1">
            <p className="text-[10px] font-bold text-blue-100 uppercase mb-1">งบประมาณรวมทั้งสิ้น</p>
            <p className="text-2xl font-black text-white">฿{summary.total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
          </div>
        </div>

        {/* 📋 จำแนกตามประเภท (Unit Breakdown) */}
        <div className="mt-6 pt-6 border-t border-slate-100">
          <p className="text-[10px] font-bold text-slate-400 uppercase mb-3 tracking-widest">จำแนกตามประเภทอุปกรณ์ (ยอดรวมรายเดือน)</p>
          <div className="flex flex-wrap gap-2">
            {Object.entries(summary.countsByType).map(([type, count]: [string, any]) => (
              <div key={type} className="bg-white border border-slate-200 px-3 py-1.5 rounded-xl flex items-center gap-2 shadow-sm">
                <span className="text-xs font-bold text-slate-700">{type}</span>
                <span className="h-4 w-px bg-slate-200"></span>
                <span className="text-xs font-black text-blue-600">{count} <span className="text-[10px] font-medium text-slate-400">เครื่อง</span></span>
              </div>
            ))}
            {Object.keys(summary.countsByType).length === 0 && (
              <p className="text-xs text-slate-400 italic">ไม่มีข้อมูลการซ่อมในเดือนนี้</p>
            )}
          </div>
        </div>
      </div>

      <div className="mb-6">
        <div className="relative max-w-md w-full">
          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-slate-400">🔍</span>
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}
            placeholder="ค้นหาด้วย ชื่อ, รหัสพนักงาน, ครุภัณฑ์, สัญญา, อุปกรณ์..."
            className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-4 py-2 text-sm focus:outline-none text-slate-800"
          />
        </div>
      </div>

      <div className="overflow-x-auto border border-slate-200 rounded-xl bg-white shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 text-xs uppercase font-bold tracking-wider">
              <th className="p-4 w-16 text-center">ลำดับ</th>
              <th className="p-4">วันที่แจ้ง/เสร็จสิ้น</th>
              <th className="p-4">รหัสพนักงาน</th>
              <th className="p-4">ผู้แจ้งซ่อม</th>
              <th className="p-4">เลขครุภัณฑ์</th>
              <th className="p-4">เลขที่สัญญา</th>
              <th className="p-4">ประเภท</th>
              <th className="p-4">อุปกรณ์ / S/N</th>
              <th className="p-4">อาการเสีย</th>
              <th className="p-4 text-center">สถานะ</th>
              <th className="p-4 text-right">ยอดรวม (บาท)</th>
              <th className="p-4 text-center">เอกสาร</th>
              <th className="p-4 text-center">จัดการ</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-sm">
            {currentRepairs.length > 0 ? (
              currentRepairs.map((repair, index) => (
                <tr key={repair.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="p-4 text-center text-slate-400 font-mono text-xs">{indexOfFirstItem + index + 1}</td>
                  <td className="p-4">
                    <div className="text-xs text-slate-500">📥 {new Date(repair.repair_date).toLocaleDateString('th-TH')}</div>
                    {repair.repair_finish && (
                      <div className="text-xs text-emerald-600 font-bold mt-1">✅ {new Date(repair.repair_finish).toLocaleDateString('th-TH')}</div>
                    )}
                  </td>
                  <td className="p-4 font-mono text-xs text-slate-600 font-bold uppercase">
                    {repair.requester_emp_code || '-'}
                  </td>
                  <td className="p-4">
                    <div className="font-semibold text-slate-900">{repair.requester_name || 'ไม่ระบุชื่อ'}</div>
                    <div className="text-[10px] text-slate-500">{repair.requester_position || '-'} | {repair.requester_dept || '-'}</div>
                    <div className="text-[10px] text-blue-600 font-mono">{repair.requester_phone || '-'}</div>
                  </td>
                  <td className="p-4 font-mono text-xs text-amber-700 font-bold">
                    {repair.item?.assets_number || '-'}
                  </td>
                  <td className="p-4 font-mono text-xs text-blue-700 font-bold">
                    {repair.item?.manual_contract || '-'}
                  </td>
                  <td className="p-4 text-xs font-semibold text-slate-600 uppercase">
                    {repair.item?.type_item || '-'}
                  </td>
                  <td className="p-4">
                    <div className="font-medium text-slate-800">{repair.item?.manual_brand || 'ไม่ระบุ'}</div>
                    <div className="text-[10px] text-slate-500 font-mono">SN: {repair.item?.manual_sn || '-'}</div>
                  </td>
                  <td className="p-4 text-slate-700 max-w-xs truncate">{repair.item?.problem_detail || '-'}</td>
                  <td className="p-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold border whitespace-nowrap ${
                      REPAIR_STATUS.find(s => s.value === repair.status)?.color || 'bg-slate-50 text-slate-700'
                    }`}>
                      {REPAIR_STATUS.find(s => s.value === repair.status)?.label.split(' ')[1] || repair.status}
                    </span>
                  </td>
                  <td className="p-4 text-right font-mono font-bold text-blue-600">
                    {repair.grand_total ? repair.grand_total.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '0.00'}
                  </td>
                  <td className="p-4 text-center">
                    {repair.file_url ? (
                      <div className="flex flex-col items-center gap-1">
                        <a
                          href={repair.file_url}
                          target="_blank"
                          rel="noreferrer"
                          className="bg-emerald-50 text-emerald-600 hover:bg-emerald-100 px-2 py-1 rounded text-[10px] font-bold border border-emerald-200 w-full"
                        >
                          👁️ ดูไฟล์
                        </a>
                        <div className="scale-90 opacity-70 hover:opacity-100 transition-opacity">
                          <RepairDocumentUploader repairId={repair.id} onUploadSuccess={fetchRepairs} />
                        </div>
                      </div>
                    ) : (
                      <RepairDocumentUploader repairId={repair.id} onUploadSuccess={fetchRepairs} />
                    )}
                  </td>
                  <td className="p-4 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <button
                        onClick={() => generateRepairPDF(repair)}
                        className="bg-slate-50 text-slate-600 hover:bg-slate-100 px-2 py-1 rounded text-[10px] font-bold border border-slate-200 whitespace-nowrap"
                      >
                        🖨️ พิมพ์ใบซ่อม
                      </button>
                      <button
                        onClick={() => openModal(repair)}
                        className="bg-blue-50 text-blue-600 hover:bg-blue-100 px-2 py-1 rounded text-[10px] font-bold border border-blue-200"
                        title="แก้ไขข้อมูล"
                      >
                        📝
                      </button>
                      <button
                        onClick={() => handleDelete(repair.id)}
                        className="bg-red-50 text-red-600 hover:bg-red-100 px-2 py-1 rounded text-[10px] font-bold border border-red-200"
                        title="ลบรายการ"
                      >
                        🗑️
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={13} className="p-8 text-center text-slate-400">❌ ไม่พบข้อมูลการซ่อม</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center space-x-2 mt-4">
          <button onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))} disabled={currentPage === 1} className="px-3 py-1 border rounded disabled:opacity-50">ก่อนหน้า</button>
          <span className="text-sm font-medium">หน้า {currentPage} / {totalPages}</span>
          <button onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))} disabled={currentPage === totalPages} className="px-3 py-1 border rounded disabled:opacity-50">ถัดไป</button>
        </div>
      )}

      {/* Modal สำหรับการแก้ไข (Edit Only) */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-xl overflow-hidden max-h-[90vh] flex flex-col">
            <div className="bg-slate-50 border-b px-6 py-4 flex justify-between items-center shrink-0">
              <h4 className="font-bold text-slate-900">📝 แก้ไขข้อมูลการซ่อม</h4>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-xl">×</button>
            </div>
            
            <form onSubmit={handleSubmit} className="p-6 space-y-4 overflow-y-auto">
              <div>
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">สถานะการซ่อม</label>
                <select value={status} onChange={(e) => setStatus(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800">
                  {REPAIR_STATUS.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                </select>
              </div>

              <div className="border-t border-slate-100 pt-4">
                <h5 className="text-[10px] font-bold text-slate-400 uppercase mb-3 tracking-widest">ข้อมูลผู้แจ้งซ่อม</h5>
                <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">ชื่อผู้แจ้ง</label>
                    <input type="text" value={requesterName} onChange={(e) => setRequesterName(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-bold uppercase text-slate-500 mb-1">รหัสพนักงาน</label>
                      <input type="text" value={requesterEmpCode} onChange={(e) => setRequesterEmpCode(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-slate-500 mb-1">ตำแหน่ง</label>
                      <input type="text" value={requesterPosition} onChange={(e) => setRequesterPosition(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-bold uppercase text-slate-500 mb-1">แผนก</label>
                      <input type="text" value={requesterDept} onChange={(e) => setRequesterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-slate-500 mb-1">เบอร์โทร</label>
                      <input type="text" value={requesterPhone} onChange={(e) => setRequesterPhone(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="border-t border-slate-100 pt-4">
                <div>
                  <label className="block text-xs font-bold uppercase text-slate-500 mb-1">ประเภทอุปกรณ์</label>
                  <input type="text" value={typeItem} onChange={(e) => setTypeItem(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800" />
                </div>
                <div className="grid grid-cols-2 gap-3 mt-3">
                  <div>
                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">เลขครุภัณฑ์</label>
                    <input type="text" value={assetsNumber} onChange={(e) => setAssetsNumber(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800 font-mono" />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase text-slate-500 mb-1">เลขที่สัญญา</label>
                    <input type="text" value={manualContract} onChange={(e) => setManualContract(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800 font-mono" />
                  </div>
                </div>
              </div>

              <div className="border-t border-slate-100 pt-4">
                <label className="block text-xs font-bold uppercase text-slate-500 mb-1">อาการเสีย (แก้ไข)</label>
                <textarea
                  value={problemDetail}
                  onChange={(e) => setProblemDetail(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:border-blue-500 text-slate-800"
                  rows={3}
                />
              </div>

              <div className="flex space-x-3 pt-4 border-t sticky bottom-0 bg-white shrink-0">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-600 font-semibold py-2 rounded-xl text-sm transition-colors">ยกเลิก</button>
                <button type="submit" className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 rounded-xl text-sm shadow-sm transition-colors">บันทึกการแก้ไข</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Swal from 'sweetalert2'

export default function SparePartsTable() {
  const [parts, setParts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')

  // Modal states
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [editingPart, setEditingPart] = useState<any | null>(null)

  // Form states
  const [partName, setPartName] = useState('')
  const [partBrand, setPartBrand] = useState('')
  const [partSN, setPartSN] = useState('')
  const [stockQuantity, setStockQuantity] = useState(0)
  const [unitPrice, setUnitPrice] = useState(0)
  const [dateIn, setDateIn] = useState('')
  const [dateOut, setDateOut] = useState('')

  const fetchParts = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/spare-parts')
      const json = await res.json()
      if (json.success) setParts(json.data || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchParts()
  }, [])

  const openModal = (part: any | null = null) => {
    if (part) {
      setEditingPart(part)
      setPartName(part.part_name || '')
      setPartBrand(part.part_brand || '')
      setPartSN(part.part_serial_umber || '')
      setStockQuantity(part.stock_quantity || 0)
      setUnitPrice(part.unit_price || 0)
      setDateIn(part.part_date_in ? new Date(part.part_date_in).toISOString().split('T')[0] : '')
      setDateOut(part.part_date_out ? new Date(part.part_date_out).toISOString().split('T')[0] : '')
    } else {
      setEditingPart(null)
      setPartName('')
      setPartBrand('')
      setPartSN('')
      setStockQuantity(0)
      setUnitPrice(0)
      setDateIn(new Date().toISOString().split('T')[0])
      setDateOut('')
    }
    setIsModalOpen(true)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const bodyData = { 
      part_name: partName, 
      part_brand: partBrand,
      part_serial_umber: partSN,
      stock_quantity: stockQuantity, 
      unit_price: unitPrice,
      part_date_in: dateIn || null,
      part_date_out: dateOut || null
    }

    try {
      const url = editingPart ? `/api/spare-parts/${editingPart.id}` : '/api/spare-parts'
      const method = editingPart ? 'PATCH' : 'POST'
      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyData),
      })

      const json = await res.json()
      if (json.success) {
        setIsModalOpen(false)
        Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', timer: 1500, showConfirmButton: false })
        fetchParts()
      }
    } catch (err) {
      Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด' })
    }
  }

  const handleDelete = async (id: number) => {
    const result = await Swal.fire({
      title: 'ยืนยันการลบ?',
      text: "คุณต้องการลบอะไหล่ชิ้นนี้ใช่หรือไม่?",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'ลบเลย',
      cancelButtonText: 'ยกเลิก'
    })

    if (!result.isConfirmed) return

    try {
      const res = await fetch(`/api/spare-parts/${id}`, { method: 'DELETE' })
      const json = await res.json()
      if (json.success) {
        Swal.fire({ icon: 'success', title: 'ลบสำเร็จ', timer: 1500, showConfirmButton: false })
        fetchParts()
      }
    } catch (err) {
      Swal.fire({ icon: 'error', title: 'ลบไม่สำเร็จ' })
    }
  }

  const filteredParts = parts.filter(p => 
    p.part_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.part_brand?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.part_serial_umber?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  if (loading) return <div className="p-12 text-center text-slate-400 animate-pulse">กำลังโหลดคลังอะไหล่...</div>

  return (
    <div className="p-6">
      <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-4 mb-6">
        <div>
          <h3 className="text-lg font-bold text-slate-900">คลังอะไหล่ (Spare Parts Stock)</h3>
          <p className="text-xs text-slate-500">จัดการรายละเอียดอะไหล่ ยี่ห้อ S/N และวันที่นำเข้า-ส่งออก</p>
        </div>
        <button
          onClick={() => openModal()}
          className="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-100 flex items-center justify-center gap-2 active:scale-95"
        >
          ➕ เพิ่มอะไหล่ใหม่
        </button>
      </div>

      <div className="mb-6 max-w-md">
        <div className="relative">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-400">🔍</span>
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="ค้นหาชื่ออะไหล่, ยี่ห้อ, Serial Number..."
            className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-10 pr-4 py-2.5 text-sm focus:outline-none focus:border-emerald-500 focus:bg-white transition-all"
          />
        </div>
      </div>

      <div className="overflow-x-auto border border-slate-200 rounded-3xl bg-white">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 text-slate-500 text-[10px] uppercase font-bold tracking-widest border-b border-slate-100">
              <th className="p-4">รายการ / ยี่ห้อ</th>
              <th className="p-4">Serial Number</th>
              <th className="p-4 text-center">คงเหลือ</th>
              <th className="p-4 text-right">ราคา/หน่วย</th>
              <th className="p-4">วันที่นำเข้า</th>
              <th className="p-4 text-center">จัดการ</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredParts.length > 0 ? (
              filteredParts.map((part) => (
                <tr key={part.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="p-4">
                    <div className="font-bold text-slate-900 text-sm group-hover:text-emerald-600 transition-colors">{part.part_name}</div>
                    <div className="text-[10px] text-slate-400 font-medium uppercase">{part.part_brand || '-'}</div>
                  </td>
                  <td className="p-4 font-mono text-xs text-slate-500">
                    {part.part_serial_umber || '-'}
                  </td>
                  <td className="p-4 text-center">
                     <span className={`px-2.5 py-1 rounded-lg font-bold text-[10px] border ${part.stock_quantity > 5 ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-red-50 text-red-700 border-red-100'}`}>
                      {part.stock_quantity} ชิ้น
                     </span>
                  </td>
                  <td className="p-4 text-right font-mono text-xs text-slate-600 font-bold">
                    {new Intl.NumberFormat('th-TH', { style: 'currency', currency: 'THB' }).format(part.unit_price)}
                  </td>
                  <td className="p-4 text-[10px] text-slate-500">
                    {part.part_date_in ? new Date(part.part_date_in).toLocaleDateString('th-TH') : '-'}
                  </td>
                  <td className="p-4 text-center">
                    <div className="flex justify-center gap-1">
                      <button onClick={() => openModal(part)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">✏️</button>
                      <button onClick={() => handleDelete(part.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors">🗑️</button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={6} className="p-12 text-center text-slate-400 text-sm italic">ไม่พบข้อมูลอะไหล่ในสต็อก</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-[2rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-900 px-8 py-5 flex justify-between items-center text-white">
              <h4 className="font-bold text-lg">{editingPart ? '📝 แก้ไขข้อมูลอะไหล่' : '➕ เพิ่มอะไหล่ใหม่'}</h4>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white text-3xl leading-none">×</button>
            </div>
            
            <form onSubmit={handleSubmit} className="p-8 space-y-5 max-h-[75vh] overflow-y-auto">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="md:col-span-2">
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">ชื่ออะไหล่ <span className="text-red-500">*</span></label>
                  <input type="text" value={partName} onChange={(e) => setPartName(e.target.value)} placeholder="เช่น RAM DDR4 8GB" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" required />
                </div>
                
                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">ยี่ห้อ (Brand)</label>
                  <input type="text" value={partBrand} onChange={(e) => setPartBrand(e.target.value)} placeholder="เช่น Kingston, WD" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" />
                </div>
                
                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">Serial Number</label>
                  <input type="text" value={partSN} onChange={(e) => setPartSN(e.target.value)} placeholder="ระบุ S/N" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all font-mono" />
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">จำนวนในสต็อก</label>
                  <input type="number" value={stockQuantity} onChange={(e) => setStockQuantity(parseInt(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" required />
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">ราคาต่อหน่วย (บาท)</label>
                  <input type="number" step="0.01" value={unitPrice} onChange={(e) => setUnitPrice(parseFloat(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" required />
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">วันที่นำเข้า</label>
                  <input type="date" value={dateIn} onChange={(e) => setDateIn(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" />
                </div>

                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-1.5 tracking-widest">วันที่ส่งออก</label>
                  <input type="date" value={dateOut} onChange={(e) => setDateOut(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:border-emerald-500 focus:bg-white outline-none transition-all" />
                </div>
              </div>

              <div className="flex gap-4 pt-6 border-t border-slate-100">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold py-3.5 rounded-2xl transition-all">ยกเลิก</button>
                <button type="submit" className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3.5 rounded-2xl shadow-lg shadow-emerald-100 transition-all active:scale-95">บันทึกข้อมูลอะไหล่</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

// scripts/download-font.js
// ดาวน์โหลดฟอนต์ Sarabun (TTF) จาก Google Fonts GitHub และบันทึกที่ public/fonts/THSarabunNew.ttf
const https = require('https');
const fs = require('fs');
const path = require('path');

const url = 'https://raw.githubusercontent.com/google/fonts/main/ofl/sarabun/Sarabun-Regular.ttf';
const outDir = path.join(__dirname, '..', 'public', 'fonts');
const outPath = path.join(outDir, 'THSarabunNew.ttf');

function download(url, dest) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      if (res.statusCode !== 200) return reject(new Error('Failed to download font, status ' + res.statusCode));
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      const file = fs.createWriteStream(dest);
      res.pipe(file);
      file.on('finish', () => file.close(resolve));
      file.on('error', (err) => reject(err));
    }).on('error', (err) => reject(err));
  });
}

download(url, outPath)
  .then(() => console.log('Font downloaded to', outPath))
  .catch((err) => {
    console.error('Download failed:', err.message);
    process.exit(1);
  });
